head.b:template-skin:
body#layout::-webkit-scrollbar{width:10px;height:10px}
body#layout::-webkit-scrollbar-track{background:#f3efe6}
body#layout::-webkit-scrollbar-thumb{background:#141414}
body#layout{position:relative;background:#f3efe6!important;background-image:radial-gradient(rgba(20,20,20,.15) .7px,transparent .8px)!important;background-size:20px 20px!important;font-family:'Space Grotesk',Arial,sans-serif;margin:0 auto!important;padding:16px 8px 32px!important;border:0!important;text-align:left!important;max-width:1080px!important;color:#141414}
body#layout .layout-title{font-size:15px!important;font-weight:700;white-space:nowrap;overflow:hidden;color:#141414}

/* Sembunyikan elemen tampilan (bukan pengaturan) */
body#layout .skip-link,
body#layout .menu-trigger,
body#layout .header-actions,
body#layout .header-progress,
body#layout .drawer-backdrop,
body#layout .drawer-head,
body#layout .drawer-search,
body#layout .drawer-quick,
body#layout .drawer-foot,
body#layout .drawer-section-head,
body#layout .section-heading,
body#layout .footer-cta,
body#layout .footer-bottom,
body#layout .mobile-bottom-nav,
body#layout .post-mobile-actions,
body#layout .post-share-sheet,
body#layout .post-share-sheet-backdrop,
body#layout .post-toc-drawer,
body#layout .post-toc-backdrop,
body#layout .back-top,
body#layout .sheet-backdrop,
body#layout .notice,
body#layout .bui-cart-sheet,
body#layout .bui-cart-sheet-backdrop,
body#layout .bui-cookie-banner,
body#layout #labelDescSlot{display:none!important}

/* Pembungkus dibuat blok biasa: urutan Kategori = urutan di halaman */
body#layout .site-header,
body#layout .header-inner,
body#layout .bui-config,
body#layout .left-drawer,
body#layout .drawer-body,
body#layout .drawer-body>div,
body#layout .site-main,
body#layout .content-layout,
body#layout .main-column,
body#layout .site-footer,
body#layout .footer-all{display:block!important;position:relative!important;inset:auto!important;transform:none!important;width:100%!important;max-width:100%!important;height:auto!important;min-height:0!important;padding:0!important;margin:0!important;border:0!important;background:transparent!important;box-shadow:none!important;overflow:visible!important}

/* Kartu Kategori (Section) */
body#layout div.section{display:block!important;visibility:visible!important;opacity:1!important;background:#fffdf6!important;border:3px solid #141414!important;border-left-width:12px!important;border-left-color:#d8ff3e!important;border-radius:0!important;box-shadow:6px 6px 0 #141414;margin:0 8px 24px 8px!important;padding:14px!important;width:auto!important;position:relative!important;transform:none!important}
body#layout div.section.cat-header{border-left-color:#d8ff3e!important}
body#layout div.section.cat-mobile{border-left-color:#ff8b6a!important}
body#layout div.section.cat-hero{border-left-color:#c4a1ff!important}
body#layout div.section.cat-posts{border-left-color:#7bf1a8!important}
body#layout div.section.cat-footer{border-left-color:#ff7eb6!important}
body#layout div.section.cat-sidebar{border-left-color:#8ddcff!important}
body#layout div.section.cat-another{border-left-color:#141414!important}
body#layout div.section h4{font-size:15px!important;font-weight:800!important;letter-spacing:.06em;text-transform:uppercase;margin:0 0 12px 0;padding:9px 12px;text-align:left;background:#d8ff3e;color:#141414;border:2px solid #141414;border-radius:0;box-shadow:3px 3px 0 #141414}
body#layout div.section.cat-mobile h4{background:#ff8b6a}
body#layout div.section.cat-hero h4{background:#c4a1ff}
body#layout div.section.cat-posts h4{background:#7bf1a8}
body#layout div.section.cat-footer h4{background:#ff7eb6}
body#layout div.section.cat-sidebar h4{background:#8ddcff}
body#layout div.section.cat-another h4{background:#141414;color:#d8ff3e}
body#layout div.section.cat-product{border-left-color:#5ce1e6!important}
body#layout div.section.cat-product h4{background:#5ce1e6}
body#layout div.section.cat-label{border-left-color:#ffd23e!important}
body#layout div.section.cat-label h4{background:#ffd23e}
body#layout div.section.cat-featured{border-left-color:#ff8a65!important}
body#layout div.section.cat-featured h4{background:#ff8a65}
body#layout div.section.cat-popular{border-left-color:#b388ff!important}
body#layout div.section.cat-popular h4{background:#b388ff}

/* Kartu Gadget = nama pengaturan */
body#layout .widget{display:block!important;visibility:visible!important;opacity:1!important;transform:none!important;position:relative!important;margin:10px 0!important}
body#layout .widget .widget-wrap2{border-radius:0;background:#ff8b6a!important;border:2px solid #141414}
body#layout .widget .widget-wrap3{border-radius:0;background:#fff!important}
body#layout .widget .widget-content{background:transparent!important;box-shadow:none!important;border-radius:0;height:auto!important}
body#layout .layout-widget-description{font-size:12px!important;line-height:1.5em;opacity:.75;font-family:monospace}
body#layout .add_widget{display:block;padding:0;border:none;border-radius:0}
body#layout .add-icon{display:none}
body#layout .add_widget a{display:block;font-size:14px!important;font-weight:700;margin:auto;text-decoration:none;color:#141414;background:#fffdf6;border-radius:0;padding:10px;text-align:center;border:2px dashed #141414}
body#layout .add_widget a::after{content:' ( + )'}
body#layout .add_widget a:hover{background:#d8ff3e}
body#layout .visibility .editlink.icon{height:26px!important;width:26px!important;border:2px solid #141414!important;border-radius:0!important;background-size:70%!important}
body#layout .visibility .editlink.icon:hover{background-color:#d8ff3e!important}

div.script:
document.addEventListener('DOMContentLoaded', function() {
  if (typeof BLOG_CMT_createIframe === 'function') {
    BLOG_CMT_createIframe('');
  }
});
function replyToComment(commentId) {
  var srcEl = document.getElementById('comment-editor-src');
  var editor = document.getElementById('comment-editor');
  var formWrap = document.getElementById('bui-comment-form');
  if (srcEl && editor) {
    var base = srcEl.href.split('&parentID=')[0];
    editor.src = base + '&parentID=' + encodeURIComponent(commentId);
    if (formWrap) formWrap.scrollIntoView({ behavior: 'smooth' });
  }
}

body.script:
//
(function(){
  var b=document.body;if(!b)return;
  try{
    var st=getComputedStyle(b);
    var n=function(k){return parseInt(st.getPropertyValue(k),10)};
    var pick=function(m,v,d){return m[v]||d};
    var ff=n('--bui-footer-style');
    b.setAttribute('data-font-display',pick({1:'syne',2:'bebas',3:'archivo'},n('--bui-font-display'),'syne'));
    b.setAttribute('data-font-body',pick({1:'space',2:'jakarta',3:'inter',4:'dmsans'},n('--bui-font-body'),'space'));
    b.setAttribute('data-footer-style',String(ff>=1&&ff<=7?ff:1));
    b.setAttribute('data-mob-style',['classic','floating','pill','dock','tiles','minimal','glass','tabs','notch','slab'][(n('--bui-mobile-menu-style')||1)-1]||'classic');
    b.setAttribute('data-mob-labels',n('--bui-mobile-menu-labels')===2?'off':'on');
    b.setAttribute('data-mob-shrink',n('--bui-mobile-menu-shrink')===2?'on':'off');
    b.setAttribute('data-bui-card-style',n('--bui-card-style')===2?'square':'rounded');
    b.setAttribute('data-hd-sticky',pick({1:'on',2:'off',3:'smart'},n('--bui-header-sticky'),'on'));
    b.setAttribute('data-hd-style',pick({1:'solid',2:'glass',3:'floating',4:'transparent',5:'accent'},n('--bui-header-style'),'solid'));
    b.setAttribute('data-hd-width',pick({1:'boxed',2:'full'},n('--bui-header-width'),'boxed'));
    b.setAttribute('data-hd-shrink',pick({1:'on',2:'off'},n('--bui-header-shrink'),'off'));
    b.setAttribute('data-hd-progress',pick({1:'on',2:'off'},n('--bui-header-progress'),'on'));
    b.setAttribute('data-hd-shadow',pick({1:'hard',2:'soft',3:'none'},n('--bui-header-shadow'),'hard'));
    b.setAttribute('data-glass-hd',n('--bui-glass-header')===2?'on':'off');
    b.setAttribute('data-glass-dd',n('--bui-glass-dropdown')===2?'on':'off');
    b.setAttribute('data-glass-post',n('--bui-glass-postmenu')===2?'on':'off');
    b.setAttribute('data-glass-drawer',n('--bui-glass-drawer')===2?'on':'off');
    b.setAttribute('data-glass-toc',n('--bui-glass-toc')===2?'on':'off');
    var sn=function(k,d){return n(k)||d};
    b.setAttribute('data-sidebar-style',String(Math.min(6,sn('--bui-sidebar-style',1))));
    b.setAttribute('data-toc-style',String(Math.min(5,sn('--bui-toc-style',1))));
    b.setAttribute('data-breadcrumb-style',String(Math.min(5,sn('--bui-breadcrumb-style',2))));
    b.setAttribute('data-glass-variants',sn('--bui-glass-variants',1)===2?'on':'off');
    b.setAttribute('data-glass-search',sn('--bui-glass-search',2)===1?'off':'on');
    b.setAttribute('data-skeleton',sn('--bui-skeleton',2)===1?'off':'on');
    b.setAttribute('data-post-layout',sn('--bui-posts-layout',1)===2?'list':'grid');
    document.documentElement.classList.add(n('--bui-perf-lazyload')===1?'lz-off':'lz-on');
  }catch(e){}
})();
//

