(function(){
  'use strict';
  var CART_KEY='brutalism-ui-cart-v1';
  var BOOKMARK_KEY='brutalism-ui-bookmarks-v1';
  var THEME_KEY='brutalism-ui-theme-v1';
  var COLOR_KEY='brutalism-ui-color-v1';
  var FONTSIZE_KEY='brutalism-ui-fontsize-v1';
  var DDSTYLE_KEY='brutalism-ui-ddstyle-v1';
  var LANG_KEY='brutalism-ui-language-v1';

  /* Inline SVG Constants (Zero Emoji) */
  var SVG_ARROW_UP_RIGHT='<svg viewBox="0 0 24 24" width="16" height="16" fill="none" stroke="currentColor" stroke-width="2.2" stroke-linecap="square"><path d="M7 17 17 7M9 7h8v8"/></svg>';
  var SVG_ARROW_RIGHT='<svg viewBox="0 0 24 24" width="16" height="16" fill="none" stroke="currentColor" stroke-width="2.2" stroke-linecap="square"><path d="M5 12h14m-6-6 6 6-6 6"/></svg>';
  var SVG_BOOKMARK='<svg viewBox="0 0 24 24" width="17" height="17" fill="none" stroke="currentColor" stroke-width="2"><path d="M6 4h12v17l-6-4-6 4z"/></svg>';
  var SVG_CART='<svg viewBox="0 0 24 24" width="17" height="17" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M3 4h2l2.3 11.2a2 2 0 0 0 2 1.6h7.8a2 2 0 0 0 1.9-1.4L21 8H6"/><circle cx="10" cy="20" r="1.3"/><circle cx="18" cy="20" r="1.3"/></svg>';
  var SVG_TRASH='<svg viewBox="0 0 24 24" width="14" height="14" fill="none" stroke="currentColor" stroke-width="2.2" stroke-linecap="square"><path d="M3 6h18M8 6V4h8v2m-9 0v14h10V6"/></svg>';
  var SVG_FOLDER='<svg viewBox="0 0 24 24" width="18" height="18" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M3 7v11a2 2 0 0 0 2 2h14a2 2 0 0 0 2-2V9a2 2 0 0 0-2-2h-6.5l-2-2H5a2 2 0 0 0-2 2z"/></svg>';
  var SVG_CHEVRON='<svg class="drawer-chevron" viewBox="0 0 24 24" width="16" height="16" fill="none" stroke="currentColor" stroke-width="2.2" stroke-linecap="square"><path d="m6 9 6 6 6-6"/></svg>';
  var SVG_STAR='<svg viewBox="0 0 24 24" width="14" height="14" fill="currentColor"><polygon points="12 2 15.09 8.26 22 9.27 17 14.14 18.18 21.02 12 17.77 5.82 21.02 7 14.14 2 9.27 8.91 8.26 12 2"/></svg>';
  var SVG_COPY='<svg viewBox="0 0 24 24" width="13" height="13" fill="none" stroke="currentColor" stroke-width="2"><rect x="9" y="9" width="13" height="13" rx="1"/><path d="M5 15H4a2 2 0 0 1-2-2V4a2 2 0 0 1 2-2h9a2 2 0 0 1 2 2v1"/></svg>';
  var SVG_HOME='<svg viewBox="0 0 24 24" width="19" height="19" fill="none" stroke="currentColor" stroke-width="2" stroke-linejoin="round"><path d="m3 10 9-7 9 7v10H5V10"/><path d="M9 20v-6h6v6"/></svg>';
  var SVG_BOX='<svg viewBox="0 0 24 24" width="19" height="19" fill="none" stroke="currentColor" stroke-width="2" stroke-linejoin="round"><path d="m3 7 9-4 9 4v10l-9 4-9-4z"/><path d="m3 7 9 4 9-4M12 11v10"/></svg>';
  var SVG_TAG='<svg viewBox="0 0 24 24" width="19" height="19" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M20.6 13.4 13.4 20.6a2 2 0 0 1-2.8 0L3 13V3h10l7.6 7.6a2 2 0 0 1 0 2.8z"/><circle cx="7.5" cy="7.5" r="1.2"/></svg>';
  var SVG_INFO='<svg viewBox="0 0 24 24" width="19" height="19" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round"><circle cx="12" cy="12" r="9"/><path d="M12 11v6M12 7.5v.01"/></svg>';
  var SVG_MAIL='<svg viewBox="0 0 24 24" width="19" height="19" fill="none" stroke="currentColor" stroke-width="2" stroke-linejoin="round"><rect x="3" y="5" width="18" height="14"/><path d="m3 7 9 6 9-6"/></svg>';
  var SVG_SHARE='<svg viewBox="0 0 24 24" width="17" height="17" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><circle cx="18" cy="5" r="3"/><circle cx="6" cy="12" r="3"/><circle cx="18" cy="19" r="3"/><path d="m8.6 13.5 6.8 4M15.4 6.5l-6.8 4"/></svg>';
  var SVG_ARROW_LEFT='<svg viewBox="0 0 24 24" width="18" height="18" fill="none" stroke="currentColor" stroke-width="2.4" stroke-linecap="square"><path d="M19 12H5m6-6-6 6 6 6"/></svg>';
  var SVG_CHECK='<svg viewBox="0 0 24 24" width="13" height="13" fill="none" stroke="currentColor" stroke-width="2.5"><path d="M20 6 9 17l-5-5"/></svg>';

  var $=function(sel,root){return (root||document).querySelector(sel)};
  var $$=function(sel,root){return Array.prototype.slice.call((root||document).querySelectorAll(sel))};
  function readStore(key){try{var v=JSON.parse(localStorage.getItem(key)||'[]');return Array.isArray(v)?v:[]}catch(e){return []}}
  function writeStore(key,value){try{localStorage.setItem(key,JSON.stringify(value))}catch(e){showNotice('Browser storage is unavailable.')}}
  var cart=readStore(CART_KEY), bookmarks=readStore(BOOKMARK_KEY);
  var knownProducts={};
  var kvConfig={};

  function escapeHTML(s){return String(s==null?'':s).replace(/[&<>"']/g,function(c){return {'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]})}
  function money(n){try{return new Intl.NumberFormat('id-ID',{style:'currency',currency:'IDR',maximumFractionDigits:0}).format(Number(n)||0)}catch(e){return 'Rp '+(Number(n)||0)}}
  var SVG_BM_CHECK='<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.9" stroke-linecap="round" stroke-linejoin="round"><path d="M17 3H7a2 2 0 0 0-2 2v16l7-4 7 4V5"/><path d="m9 9 2 2 4-4"/></svg>';
  var SVG_X_N='<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round"><path d="M6 6l12 12M18 6 6 18"/></svg>';
  function showNotice(text){
    var n=$('#notice');if(!n)return;
    var t=String(text),ico=/bookmark/i.test(t)?SVG_BM_CHECK:(/cart|keranjang/i.test(t)?SVG_CART:SVG_INFO);
    n.innerHTML='<span class="nt-ico">'+ico+'</span><span class="nt-text">'+escapeHTML(t)+'</span><button class="nt-close" type="button" aria-label="Close">'+SVG_X_N+'</button>';
    n.classList.add('show');clearTimeout(showNotice.timer);showNotice.timer=setTimeout(function(){n.classList.remove('show')},3400);
  }
  function sameId(a,b){return String(a)===String(b)}
  /* ---------- v1.1.8: Lazyload (lazysizes) + ukuran gambar Blogger ---------- */
  var LZ_ON=document.documentElement.classList.contains('lz-on');
  var LZ_GIF='data:image/gif;base64,R0lGODlhAQABAIAAAAAAAP///yH5BAEAAAAALAAAAAABAAEAAAIBRAA7';
  function resizeUrl(u,w,crop){
    u=String(u||'');
    if(!/(googleusercontent\.com|blogspot\.com|ggpht\.com|bp\.blogspot\.com)/.test(u))return u;
    var sz='s'+w+(crop?'-c':'');
    return u.replace(/\/s\d+(-c)?\//,'/'+sz+'/').replace(/\/w\d+-h\d+(-[a-z-]+)?\//,'/'+sz+'/').replace(/=s\d+(-c)?(?=$|\?)/,'='+sz).replace(/=w\d+-h\d+(-[a-z-]+)?(?=$|\?)/,'='+sz);
  }
  function lzImg(src,alt,cls,w,h,crop,onerr){
    src=String(src||'');
    var big=resizeUrl(src,w,crop),resized=big!==src;
    var set=resized?[Math.round(w*.67),w,Math.round(w*1.5)].map(function(x){return resizeUrl(src,x,crop)+' '+x+'w'}).join(', '):'';
    var er=onerr?' onerror="'+onerr+'"':'';
    if(LZ_ON)return '<img class="lazyload'+(cls?' '+cls:'')+'" alt="'+escapeHTML(alt||'')+'" data-src="'+escapeHTML(big)+'"'+(set?' data-srcset="'+escapeHTML(set)+'" data-sizes="auto"':'')+' decoding="async" width="'+w+'" height="'+h+'" src="'+LZ_GIF+'"'+er+'/>';
    return '<img'+(cls?' class="'+cls+'"':'')+' alt="'+escapeHTML(alt||'')+'" src="'+escapeHTML(big)+'"'+(set?' srcset="'+escapeHTML(set)+'"':'')+' loading="lazy" decoding="async" width="'+w+'" height="'+h+'"'+er+'/>';
  }
  function initBodyImages(){
    $$('.article-content img').forEach(function(im){
      var w=im.getAttribute('data-original-width'),h=im.getAttribute('data-original-height');
      if(w&&h&&!im.getAttribute('width')&&!im.getAttribute('height')){im.setAttribute('width',w);im.setAttribute('height',h)}
      if(!im.getAttribute('decoding'))im.setAttribute('decoding','async');
    });
  }
  function thumbHTML(src){return src?lzImg(src,'','',160,160,true,'this.outerHTML=\'<div class=&quot;thumb-ph&quot;>No Thumbnail</div>\''):'<div class="thumb-ph">No Thumbnail</div>'}

  /* ---------- Read Key-Value Settings from LinkList3 ---------- */
  function readKVSettings(){
    $$('#bui-kv-settings .bui-kv-pair').forEach(function(el){
      var k=String(el.getAttribute('data-key')||'').trim().toLowerCase().replace(/^data-/,'');
      var v=String(el.getAttribute('data-val')||'').trim();
      /* Blogger LinkList sometimes prefixes relative strings with http://, strip if not a real URL */
      if(k!=='og-image' && v.indexOf('http://')===0 && v.indexOf('.')===-1){
        v=v.replace(/^http:\/\//,'');
      }
      if(k)kvConfig[k]=v;
    });
  }

  /* ---------- Header Icons: urutan & ikon custom dari Tata Letak (gadget Header Icons) ---------- */
  function initHeaderIconsOrder(){
    var bar=$('#headerActionsBar');if(!bar)return;
    var items=parseIconItems('.bui-hdr-item');
    if(!items.length)items=['Settings','Theme','Bookmark','Cart'].map(function(n){return {label:n,icon:'',link:''}});
    var HB={settings:'settings',setting:'settings',pengaturan:'settings',theme:'theme',tema:'theme',dark:'theme','dark mode':'theme',mode:'theme',bookmark:'bookmark',bookmarks:'bookmark',saved:'bookmark',save:'bookmark',cart:'cart',keranjang:'cart',translate:'translate',language:'translate',bahasa:'translate',lang:'translate',search:'search',cari:'search'};
    var map={};
    $$('[data-header-item]',bar).forEach(function(el){map[String(el.getAttribute('data-header-item')).toLowerCase()]=el;el.classList.add('is-disabled')});
    items.forEach(function(it,i){
      var key=HB[String(it.label).toLowerCase()];
      if(key==='theme')return;
      if(key&&map[key]){map[key].classList.remove('is-disabled');map[key].style.display='';bar.appendChild(map[key]);return}
      var wrap=document.createElement('div');wrap.className='header-action-item';wrap.setAttribute('data-header-item','custom-'+i);
      var a=document.createElement('a');a.className='icon-button';a.href=it.link||'#';a.title=it.label;a.setAttribute('aria-label',it.label);
      if(isExt(it.link)){a.target='_blank';a.rel='noopener'}
      a.innerHTML=iconSVG(it.icon||it.label);
      wrap.appendChild(a);bar.appendChild(wrap);
    });
  }

  /* ---------- Sidebar Drawer: Build Nested Dropdowns from LinkList2 & 4 Styles ---------- */
  /* ---------- v1.1.7: Navigation Links (tiap gadget Daftar Link = 1 kategori) & Footer ---------- */
  function cleanSvg(str){
    str=String(str||'').trim();
    if(!/^<svg[\s>]/i.test(str))return '';
    var t=document.createElement('template');t.innerHTML=str;
    var sv=t.content.querySelector('svg');
    if(!sv||!sv.children.length)return '';
    $$('script,foreignObject,iframe,object,embed,use',sv).forEach(function(n){if(n.parentNode)n.parentNode.removeChild(n)});
    [sv].concat($$('*',sv)).forEach(function(el){
      Array.prototype.slice.call(el.attributes).forEach(function(a){
        if(/^on/i.test(a.name)||/javascript:/i.test(a.value))el.removeAttribute(a.name);
      });
    });
    sv.removeAttribute('width');sv.removeAttribute('height');
    if(!sv.hasAttribute('fill')&&!sv.hasAttribute('stroke')){
      sv.setAttribute('fill','none');sv.setAttribute('stroke','currentColor');sv.setAttribute('stroke-width','2');
      sv.setAttribute('stroke-linecap','round');sv.setAttribute('stroke-linejoin','round');
    }
    sv.setAttribute('aria-hidden','true');
    return sv.outerHTML;
  }
  function parseNavLinkText(raw){
    var s=String(raw||'').trim(),customSvg='';
    var m=s.match(/\[\s*(<svg[\s\S]*?<\/svg>)\s*\]/i);
    if(m){
      customSvg=cleanSvg(m[1]);
      s=(s.slice(0,m.index)+s.slice(m.index+m[0].length)).trim();
    }
    var parts=s.split('|');
    return {
      name:(parts[0]||'').trim(),
      badge:(parts[1]||'').trim(),
      svg:customSvg
    };
  }
  function buildNavCategories(){
    var cats=$$('#leftDrawer .bui-navcat');
    if(!cats.length)return;
    var cur=location.pathname,opened=false,built=[];
    cats.forEach(function(cat){
      var rawTitle=String(cat.getAttribute('data-cat')||'').trim()||'Menu';
      var hasBreak=/\[\s*break\s*\]\s*$/i.test(rawTitle);
      var title=rawTitle.replace(/\s*\[\s*break\s*\]\s*$/i,'').trim()||'Menu';
      var ic=$('.bui-navcat-icon',cat),svg=ic?cleanSvg(ic.getAttribute('data-svg')):'';
      var ddStyle='',items='',isCur=false;
      $$('.bui-navcat-link',cat).forEach(function(a){
        var raw=String(a.getAttribute('data-raw')||a.textContent||'').trim(),href=String(a.getAttribute('href')||'').trim();
        if(raw.toLowerCase()==='dropdown-style'){var n=parseInt(href,10);if(n>=1&&n<=4)ddStyle=' dd-style-'+n;return}
        var parsed=parseNavLinkText(raw);
        if(!parsed.name)return;
        if(a.pathname===cur&&a.hostname===location.hostname)isCur=true;
        var itemIco=parsed.svg?'<span class="drawer-ico">'+parsed.svg+'</span>':dIco(parsed.name,href);
        items+='<li><a href="'+escapeHTML(href)+'"><span class="drawer-link-left">'+itemIco+'<span>'+escapeHTML(parsed.name)+'</span></span>'+(parsed.badge?'<span class="drawer-badge">'+escapeHTML(parsed.badge)+'</span>':'')+SVG_ARROW_UP_RIGHT+'</a></li>';
      });
      var ico=svg?'<span class="drawer-ico">'+svg+'</span>':dIco(title,'#kategori');
      var ul=document.createElement('ul');ul.className='drawer-nav-list';
      ul.innerHTML='<li class="drawer-dropdown'+ddStyle+'"><button type="button" class="drawer-link drawer-dd-toggle"><span class="drawer-link-left">'+ico+'<span>'+escapeHTML(title)+'</span></span>'+SVG_CHEVRON+'</button><ul class="drawer-sub">'+items+'</ul></li>';
      if(isCur&&!opened){ul.firstChild.classList.add('open');opened=true}
      cat.parentNode.replaceChild(ul,cat);built.push(ul);
      if(hasBreak){var sep=document.createElement('div');sep.className='drawer-nav-break';sep.setAttribute('role','separator');sep.setAttribute('aria-label','Navigation separator');sep.innerHTML='<span></span>';ul.parentNode.insertBefore(sep,ul.nextSibling);}
    });
    if(!opened&&built[0])built[0].firstChild.classList.add('open');
  }
  function initPopular(){
    $$('.pop-thumb img').forEach(function(img){
      var u=img.getAttribute('src')||'',n=u.replace(/\/s\d+(-c)?\//,'/s240-c/').replace(/=s\d+(-c)?$/,'=s240-c');
      if(n!==u)img.setAttribute('src',n);
    });
  }
  function initFooter(){
