  function initSidebarDropdowns(){
    buildNavCategories();

    var drawer=$('#leftDrawer');
    var cssDDStyle=1;
    try{
      cssDDStyle=parseInt(getComputedStyle(document.body).getPropertyValue('--bui-dropdown-style'),10);
    }catch(e){}
    var activeStyle=(cssDDStyle>=1 && cssDDStyle<=4)?String(cssDDStyle):(kvConfig['dropdown-style']||'1');
    if(drawer){
      ['1','2','3','4'].forEach(function(n){drawer.classList.remove('dd-style-'+n)});
      drawer.classList.add('dd-style-'+activeStyle);
