      if(parent)parent.classList.toggle('open');
    });
  }

  /* ---------- v1.1.8: Syntax Highlighter (Adaptive + Code Markers) + Line Numbers + UI Components ---------- */
  function highlightSyntax(raw,lang,marks){
    var s=escapeHTML(raw);
    var l=String(lang||'').toLowerCase().replace(/^\./,'');
    var stash=[];
    function save(html){var id='\x00T_'+stash.length+'_\x00';stash.push(html);return id}
    function restore(str){
      var prev;
      do{
        prev=str;
        str=str.replace(/\x00T_(\d+)_\x00/g,function(_,i){return stash[Number(i)]||''});
      }while(str!==prev && str.indexOf('\x00T_')!==-1);
      if(marks&&marks.length){
        str=str.replace(/\x00MKS_(\d+)_\x00/g,function(_,i){return (marks[Number(i)]&&marks[Number(i)].open)||''});
        str=str.replace(/\x00MKE_(\d+)_\x00/g,'</mark>');
      }
      return str;
    }
    if(l==='html'||l==='xml'||l==='svg'){
      s=s.replace(/(&lt;!--[\s\S]*?--&gt;)/g,function(m){return save('<span class="tk-com">'+m+'</span>')});
      s=s.replace(/(&lt;\/?)([a-zA-Z0-9:_-]+)([\s\S]*?)(\/?&gt;)/g,function(_,open,tag,attrs,close){
        var a=attrs.replace(/([a-zA-Z0-9:_-]+)(\s*=\s*)(&quot;(?:(?!&quot;)[\s\S])*?&quot;|&#39;(?:(?!&#39;)[\s\S])*?&#39;|[^\s&]+)/g,function(__,an,eq,av){
          return save('<span class="tk-attr">'+an+'</span>'+eq+'<span class="tk-str">'+av+'</span>');
        });
        return save('<span class="tk-op">'+open+'</span><span class="tk-tag">'+tag+'</span>'+a+'<span class="tk-op">'+close+'</span>');
      });
      return restore(s);
    }
    if(l==='css'||l==='scss'){
      s=s.replace(/(\/\*[\s\S]*?\*\/)/g,function(m){return save('<span class="tk-com">'+m+'</span>')});
      s=s.replace(/(&quot;.*?&quot;|&#39;.*?&#39;)/g,function(m){return save('<span class="tk-str">'+m+'</span>')});
      s=s.replace(/([\w-]+)(\s*:)/g,function(_,p,c){return save('<span class="tk-attr">'+p+'</span>')+c});
      s=s.replace(/(#[0-9a-fA-F]{3,8}\b|\b\d+(?:\.\d+)?(?:px|rem|em|vh|vw|%|s|ms|deg)?\b)/g,function(m){return save('<span class="tk-num">'+m+'</span>')});
      s=s.replace(/(@[a-zA-Z_-]+)/g,function(m){return save('<span class="tk-kw">'+m+'</span>')});
      return restore(s);
    }
    /* JS, TS, PHP, Python, JSON, Bash, SQL, etc. */
    s=s.replace(/(\/\*[\s\S]*?\*\/|\/\/[^\n]*|#(?!\d+;)[^\n]*|&quot;(?:\\(?:&quot;|&#39;|[^\n])|(?!&quot;)[^\n\\])*&quot;|&#39;(?:\\(?:&quot;|&#39;|[^\n])|(?!&#39;)[^\n\\])*&#39;|`(?:\\[\s\S]|[^`\\])*`)/g,function(m){var c=m.charAt(0);return save('<span class="'+((c==='/'||c==='#')?'tk-com':'tk-str')+'">'+m+'</span>')});
    if(l==='json'){
      s=s.replace(/\x00T_(\d+)_\x00(\s*:)/g,function(_,i,c){
        var inner=stash[Number(i)].replace(/^<span class="tk-str">|<\/span>$/g,'');
        return save('<span class="tk-attr">'+inner+'</span>')+c;
      });
    }
    s=s.replace(/(\$[a-zA-Z_][a-zA-Z0-9_]*)/g,function(m){return save('<span class="tk-var">'+m+'</span>')});
    s=s.replace(/\b(function|return|var|let|const|if|else|elif|for|while|do|switch|case|break|continue|new|class|extends|import|from|export|default|async|await|try|catch|finally|throw|true|false|null|undefined|def|print|None|True|False|echo|public|private|protected|static|namespace|use|foreach|as|array|SELECT|FROM|WHERE|INSERT|INTO|UPDATE|DELETE|JOIN|ORDER|BY|LIMIT)\b/g,function(m){return save('<span class="tk-kw">'+m+'</span>')});
    s=s.replace(/\b([a-zA-Z_][a-zA-Z0-9_]*)(?=\s*\()/g,function(m){return save('<span class="tk-fn">'+m+'</span>')});
    s=s.replace(/\b(\d+(?:\.\d+)?)\b/g,function(m){return save('<span class="tk-num">'+m+'</span>')});
    return restore(s);
  }

  function splitHtmlLines(html){
    var out=[],cur='',stack=[],re=/<\/?[a-zA-Z][^>]*>|\n|[^<\n]+|</g,m,i,t,nm;
    while((m=re.exec(html))){
      t=m[0];
      if(t==='\n'){
        for(i=stack.length-1;i>=0;i--)cur+='</'+stack[i].name+'>';
        out.push(cur);cur='';
        for(i=0;i<stack.length;i++)cur+=stack[i].open;
      }else if(t.length>1&&t.charAt(0)==='<'){
        if(t.charAt(1)==='/'){stack.pop();cur+=t}
        else{nm=/^<([a-zA-Z0-9]+)/.exec(t)[1].toLowerCase();stack.push({name:nm,open:t});cur+=t}
      }else cur+=t;
    }
    out.push(cur);
    return out;
  }

  var SVG_ZIP_BOX='<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round"><path d="M14 2H6a2 2 0 0 0-2 2v16a2 2 0 0 0 2 2h12a2 2 0 0 0 2-2V8z"/><polyline points="14 2 14 8 20 8"/><path d="M10 12h2M10 15h2M10 9h2"/><rect x="9" y="17" width="4" height="3" rx=".5"/></svg>';
  var SVG_DL_ICON='<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M12 3v12m0 0-4-4m4 4 4-4M4 17v2a2 2 0 0 0 2 2h12a2 2 0 0 0 2-2v-2"/></svg>';

  function initPlusUIComponents(){
    $$('.article-content pre').forEach(function(pre){
      if(pre.getAttribute('data-bui-hl')==='1')return;
      pre.setAttribute('data-bui-hl','1');
      var code=$('code',pre);
      var cls=((pre.className||'')+' '+(code?code.className:'')).trim();
      var lang=pre.getAttribute('data-lang')||'';
      if(!lang){
        var m=cls.match(/(?:language-|lang-|\b)(html|xml|svg|css|scss|js|javascript|ts|json|php|py|python|bash|sh|sql|code)\b/i);
        lang=m?m[1].toLowerCase():'html';
      }
      if(lang==='javascript')lang='js';
      if(lang==='python')lang='py';
      var dispLang=lang.charAt(0)==='.'?lang:('.'+lang.toLowerCase());
      pre.setAttribute('data-lang',dispLang);

      /* Ekstrak elemen <mark> asli di dalam blok kode agar berfungsi sebagai Code Marker */
      var srcEl=code||pre;
      var clone=srcEl.cloneNode(true);
      var marks=[];
      $$('mark',clone).forEach(function(mk,idx){
        var clsAttr=mk.getAttribute('class');
        var db=mk.getAttribute('data-before');
        var da=mk.getAttribute('data-after');
        var openTag='<mark'+(clsAttr?' class="'+escapeHTML(clsAttr)+'"':'')+(db!==null?' data-before="'+escapeHTML(db)+'"':'')+(da!==null?' data-after="'+escapeHTML(da)+'"':'')+'>';
        marks.push({open:openTag});
        var txtNode=document.createTextNode('\x00MKS_'+idx+'_\x00'+(mk.textContent||'')+'\x00MKE_'+idx+'_\x00');
        if(mk.parentNode)mk.parentNode.replaceChild(txtNode,mk);
      });

      var rawWithMarks=(clone.textContent||'').replace(/\r\n?/g,'\n').replace(/^\n/, '').replace(/\s+$/, '');
      var rawClean=rawWithMarks.replace(/\x00MK[SE]_\d+_\x00/g,'');
      var lines=rawClean.split('\n');
      var rows=splitHtmlLines(highlightSyntax(rawWithMarks,lang,marks));
      var rowsHtml='';
      for(var i=0;i<lines.length;i++)rowsHtml+='<span class="bui-row"><span class="bui-ln" aria-hidden="true">'+(i+1)+'</span><span class="bui-lc">'+(rows[i]||'')+'</span></span>';

      var wrap=document.createElement('div');
      wrap.className='bui-code-wrap';
      wrap.innerHTML='<code style="--ln-w:'+String(lines.length).length+'">'+rowsHtml+'</code>';
      pre.innerHTML='';
      pre.appendChild(wrap);

      var actWrap=document.createElement('div');
      actWrap.className='code-actions';

      var hasDl=pre.hasAttribute('data-download')||pre.hasAttribute('data-file')||pre.classList.contains('dl');
      if(hasDl){
        var extMap={html:'html',xml:'xml',svg:'svg',css:'css',scss:'scss',js:'js',ts:'ts',json:'json',php:'php',py:'py',bash:'sh',sh:'sh',sql:'sql'};
        var defName='snippet.'+(extMap[lang]||'txt');
        var fName=pre.getAttribute('data-file')||pre.getAttribute('data-download');
        if(!fName||fName==='true'||fName==='1')fName=defName;
        var dlBtn=document.createElement('button');
        dlBtn.type='button';
        dlBtn.className='code-dl-btn';
        dlBtn.innerHTML='<span>Download</span>'+SVG_DL_ICON;
        dlBtn.addEventListener('click',function(){
          try{
            var blob=new Blob([rawClean],{type:'text/plain;charset=utf-8'});
            var url=URL.createObjectURL(blob);
            var a=document.createElement('a');
            a.href=url;a.download=fName;
            document.body.appendChild(a);a.click();
            setTimeout(function(){document.body.removeChild(a);URL.revokeObjectURL(url)},150);
            showNotice('Mengunduh file: '+fName);
          }catch(e){showNotice('Gagal mengunduh file kode')}
        });
        actWrap.appendChild(dlBtn);
      }

      var btn=document.createElement('button');
      btn.type='button';
      btn.className='code-copy-btn';
      btn.innerHTML='<span>Copy</span>'+SVG_COPY;
      btn.addEventListener('click',function(){
        if(navigator.clipboard&&navigator.clipboard.writeText){
          navigator.clipboard.writeText(rawClean).then(function(){
            btn.innerHTML='<span>Copied</span>'+SVG_CHECK;
            setTimeout(function(){btn.innerHTML='<span>Copy</span>'+SVG_COPY},2000);
          });
        }
      });
      actWrap.appendChild(btn);
      pre.appendChild(actWrap);
    });

    /* Auto Icons pada Button (.button[data-icon]) & Download Box (.dlBox) */
    $$('.article-content .button[data-icon]').forEach(function(b){
      if(!$('svg',b)){
        b.insertAdjacentHTML('afterbegin',iconSVG(b.getAttribute('data-icon')));
      }
    });
    $$('.article-content .dlBox').forEach(function(box){
      var ft=$('.fT',box);
      if(ft&&!ft.children.length&&!ft.getAttribute('data-text')){
        var icName=ft.getAttribute('data-icon');
        ft.innerHTML=icName?iconSVG(icName):SVG_ZIP_BOX;
      }
      var btn=$('a.button, a:not(.fT)',box);
      if(btn&&!$('svg',btn)){
        btn.insertAdjacentHTML('afterbegin',SVG_DL_ICON);
      }
    });
    /* Blurred Text Spoiler: One-way reveal saat diklik atau ditekan Enter/Space */
    $$('.article-content .spoiler, .article-content .blur-spoiler').forEach(function(sp){
      if(!sp.hasAttribute('tabindex'))sp.setAttribute('tabindex','0');
      sp.setAttribute('role','button');
      sp.setAttribute('aria-label','Klik untuk membuka teks spoiler');
      function reveal(){
        sp.classList.add('is-revealed');
        sp.removeAttribute('role');
        sp.removeAttribute('aria-label');
      }
      sp.addEventListener('click',reveal);
      sp.addEventListener('keydown',function(e){
        if(e.key==='Enter'||e.key===' '){e.preventDefault();reveal()}
      });
    });

    $$('.article-content .aToc').forEach(function(tocBox){
      var article=$('.article-content');
      if(!article)return;
      var heads=$$('h2, h3, h4',article);
      if(!heads.length)return;
      var html='<ol>';
      heads.forEach(function(h,idx){
        if(!h.id)h.id='section-'+(idx+1);
        html+='<li><a href="#'+escapeHTML(h.id)+'">'+escapeHTML(h.textContent.trim())+'</a></li>';
      });
      html+='</ol>';
      tocBox.innerHTML=html;
    });

    $$('.mktRow a, .bui-mkt a').forEach(function(a){
      if(a.getAttribute('data-bui-mkt')==='1')return;
      a.setAttribute('data-bui-mkt','1');
      var txt=(a.textContent||'').trim();
      var low=(txt+' '+(a.getAttribute('href')||'')).toLowerCase();
      var brand='shop',ico=SVG_BOX;
      if(/shopee/.test(low)){brand='shopee';ico='<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M6 2 3 6v14a2 2 0 0 0 2 2h14a2 2 0 0 0 2-2V6l-3-4Z"/><path d="M3 6h18"/><path d="M16 10a4 4 0 0 1-8 0"/></svg>'}
      else if(/tokopedia/.test(low)){brand='tokopedia';ico='<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="m3 7 9-4 9 4v10l-9 4-9-4z"/><circle cx="12" cy="12" r="3"/></svg>'}
      else if(/wa\.me|whatsapp/.test(low)){brand='whatsapp';ico=iconSVG('whatsapp')}
      else if(/tiktok/.test(low)){brand='tiktok';ico='<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M9 12a4 4 0 1 0 4 4V4a5 5 0 0 0 5 5"/></svg>'}
      else if(/lazada/.test(low)){brand='lazada';ico=SVG_BOX}
      else if(/gumroad/.test(low)){brand='gumroad';ico=SVG_BOX}
      else if(/lynk/.test(low)){brand='lynk';ico=SVG_BOX}
      if(!a.hasAttribute('data-mkt'))a.setAttribute('data-mkt',brand);
      if(!$('svg',a)){
        a.innerHTML=ico+'<span>'+escapeHTML(txt)+'</span><svg class="mkt-arr" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.2"><path d="M7 17 17 7M9 7h8v8"/></svg>';
      }
    });
  }

  /* ---------- Product Meta & Multi-Variation Array Reader ---------- */
  function parseVariationsAttr(raw){
    if(!raw)return [];
    try{
      var parsed=JSON.parse(raw);
      if(Array.isArray(parsed))return parsed;
    }catch(e){}
    return String(raw).split(';').map(function(grp){
      var p=grp.split(':');if(p.length<2)return null;
      var gName=p[0].trim();
      var opts=p.slice(1).join(':').split(',').map(function(o){
        var sp=o.split('|');
        return {label:(sp[0]||'').trim(),price:Number(sp[1]||0)||0,image:(sp[2]||'').trim(),badge:(sp[3]||'').trim(),stock:sp[4]!==undefined?Number(sp[4]):null};
      }).filter(function(x){return x.label});
      return opts.length?{name:gName,options:opts}:null;
    }).filter(Boolean);
  }

  function readMeta(root){
    var meta=root?(root.querySelector('[data-price]')||root.querySelector('.product-meta')):null;
    var buttons=[],variations=[];
    if(meta&&meta.attributes){
      Array.prototype.forEach.call(meta.attributes,function(at){
        var mm=/^(?:data-)?button-([a-z0-9][a-z0-9_-]*)$/i.exec(at.name);
        var url=String(at.value||'').trim();
        if(mm&&url&&url!=='#')buttons.push({key:mm[1].toLowerCase(),url:url});
      });
      variations=parseVariationsAttr(meta.getAttribute('data-variations')||meta.getAttribute('data-variants')||'');
    }
    if(root){
      $$('.product-variants-json, script[type="application/json"][data-product-variants]',root).forEach(function(sc){
        var v=parseVariationsAttr(sc.textContent);
        if(v.length)variations=v;
      });
    }
    return {
      price:meta?Number(meta.getAttribute('data-price')||0)||0:0,
      stock:meta?Number(meta.getAttribute('data-stock')||0)||0:0,
      found:!!meta,
      buttons:buttons,
      variations:variations
    };
  }

  function getSelectedVariantState(article,basePrice,baseStock,defaultImg){
    var state={delta:0,labels:[],image:defaultImg,stock:baseStock,skuSuffix:''};
    if(!article||!article._selectedVars)return state;
    Object.keys(article._selectedVars).forEach(function(gIdx){
      var opt=article._selectedVars[gIdx];
      if(!opt)return;
      state.delta+=Number(opt.price||0);
      state.labels.push((opt.groupName?opt.groupName+': ':'')+opt.label);
      if(opt.image)state.image=opt.image;
      if(opt.stock!==null&&opt.stock!==undefined&&!isNaN(Number(opt.stock)))state.stock=Number(opt.stock);
      state.skuSuffix+='__'+(opt.groupName||gIdx)+'-'+opt.label;
    });
    return state;
  }

  function getCardInfo(card){
    var tpl=$('.post-source-body',card);
    var frag=tpl?(tpl.content||tpl):null;
    var m=readMeta(frag);
    var img=$('.post-thumb img',card),link=$('.post-title a',card),title=$('.post-title',card);
    return {id:card.getAttribute('data-post-id')||((link&&link.href)||''),url:(link&&link.href)||card.getAttribute('data-post-url')||location.href,title:title?title.textContent.trim():'Untitled',image:img?img.src:'',price:m.price,stock:m.stock,found:m.found,buttons:m.buttons,variations:m.variations,isProduct:card.classList.contains('is-product'),label:(function(){var l=$$('.post-label',card).map(function(a){return a.textContent.trim()}).filter(function(x){return x.toLowerCase()!=='product'})[0];return l||''})()};
  }

  function getArticleInfo(){
    var article=$('.blog-post');
    if(!article||article.classList.contains('is-page'))return null;
    var body=$('.article-content',article);
    var m=readMeta(body);
    var labels=$$('.post-label',article).map(function(a){return a.textContent.trim().toLowerCase()});
    var title=$('h1',article),image=body?$('img',body):null;
    var baseImg=image?image.src:'';
    var baseId=article.getAttribute('data-post-id')||location.href;
    var vState=getSelectedVariantState(article,m.price,m.stock,baseImg);
    var finalPrice=Math.max(0,(Number(m.price)||0)+vState.delta);
    var varText=vState.labels.join(' • ');
    return {
      id:baseId+(vState.skuSuffix||''),
      baseId:baseId,
      url:location.href,
      title:title?title.textContent.trim():'Untitled',
      variant:varText,
      image:vState.image||baseImg,
      price:finalPrice,
      basePrice:m.price,
      stock:vState.stock,
      found:m.found,
      variations:m.variations,
      isProduct:article.classList.contains('is-product')||labels.indexOf('product')!==-1,
      label:(function(){var l=$$('.phc-labels .post-label',article).map(function(a){return a.textContent.trim()}).filter(function(x){return x.toLowerCase()!=='product'})[0];return l||''})()
    };
  }

  /* ---------- Cart + Bookmarks (with Add-to-Cart Bottom Sheet) ---------- */
  function saveCart(item){
    var addQty=Math.max(1,Number(item.qty)||1);
    var noteStr=String(item.note||'').trim();
    var found=cart.filter(function(x){return sameId(x.id,item.id) && String(x.note||'')===noteStr})[0];
    if(found){
      var max=Number(item.stock)||Number(found.stock)||99;
      if((found.qty||1)+addQty>max){showNotice('Maksimal stok tercapai ('+max+')');return}
      found.qty=(found.qty||1)+addQty;found.price=item.price||found.price;found.stock=item.stock||found.stock;
      if(item.variant)found.variant=item.variant;
      if(item.image)found.image=item.image;
      if(noteStr)found.note=noteStr;
    }else{
      cart.push({id:item.id,url:item.url,title:item.title,variant:item.variant||'',note:noteStr,image:item.image,price:item.price,stock:item.stock,qty:addQty});
    }
    writeStore(CART_KEY,cart);renderSaved();
    showNotice('Ditambahkan ke keranjang: '+item.title+(item.variant?' ('+item.variant+')':'')+' x'+addQty);
  }

  var activeSheetProduct=null, activeSheetVars={}, activeSheetQty=1;
  function openAddToCartSheet(info){
    if(!info.found&&!info.price){showNotice('Atur data-price pada postingan produk terlebih dahulu.');return}
    if(info.stock<1){showNotice('Stok produk ini sedang habis.');return}
    var sheet=$('#buiCartSheet'),backdrop=$('#buiCartSheetBackdrop');
    if(!sheet||!backdrop){saveCart(info);return}
    activeSheetProduct=info;
    activeSheetVars={};
    activeSheetQty=1;
    var noteEl=$('#buiCsNote');if(noteEl)noteEl.value='';
    var vars=Array.isArray(info.variations)?info.variations:[];
    var vWrap=$('#buiCsVariantsWrap');
    if(vWrap){
      if(!vars.length){
        vWrap.innerHTML='';
        vWrap.style.display='none';
      }else{
        vWrap.style.display='grid';
        vWrap.style.gap='14px';
        var html='';
        vars.forEach(function(grp,gIdx){
          var gName=grp.name||('Variasi '+(gIdx+1));
          var opts=Array.isArray(grp.options)?grp.options:[];
          if(!opts.length)return;
          var firstAvail=opts.filter(function(o){return o.stock===undefined||o.stock===null||Number(o.stock)>0})[0]||opts[0];
          activeSheetVars[gIdx]={groupName:gName,label:firstAvail.label,price:Number(firstAvail.price||0),image:firstAvail.image||'',stock:firstAvail.stock};
          html+='<div class="bui-cs-sec" data-cs-group="'+gIdx+'"><div class="bui-cs-sec-label"><strong>'+escapeHTML(gName)+'</strong><span data-cs-gval="'+gIdx+'">'+escapeHTML(firstAvail.label)+'</span></div><div class="bui-cs-var-grid">';
          opts.forEach(function(opt,oIdx){
            var pDelta=Number(opt.price||0);
            var dTxt=pDelta>0?('+'+money(pDelta)):(pDelta<0?money(pDelta):'Termasuk');
            var out=(opt.stock!==undefined&&opt.stock!==null&&Number(opt.stock)<1);
            var isAct=(opt===firstAvail);
            html+='<button type="button" class="bui-cs-opt'+(isAct?' active':'')+'" data-gidx="'+gIdx+'" data-oidx="'+oIdx+'"'+(out?' disabled="disabled"':'')+'>'+
              (opt.badge?'<span class="bui-cs-opt-badge">'+escapeHTML(opt.badge)+'</span>':'')+
              (opt.image?lzImg(opt.image,'','bui-cs-opt-img',160,160,true):'')+
              '<span class="bui-cs-opt-meta"><span class="bui-cs-opt-name">'+escapeHTML(opt.label)+'</span><span class="bui-cs-opt-delta">'+(out?'Stok Habis':escapeHTML(dTxt))+'</span></span></button>';
          });
          html+='</div></div>';
        });
        vWrap.innerHTML=html;
      }
    }
    syncCartSheetUI();
    document.body.classList.add('cart-sheet-open');
    sheet.setAttribute('aria-hidden','false');
    backdrop.setAttribute('aria-hidden','false');
  }

  function closeAddToCartSheet(){
    var sheet=$('#buiCartSheet'),backdrop=$('#buiCartSheetBackdrop');
    document.body.classList.remove('cart-sheet-open');
    if(sheet)sheet.setAttribute('aria-hidden','true');
    if(backdrop)backdrop.setAttribute('aria-hidden','true');
  }

  function getSheetComputedState(){
    var p=activeSheetProduct||{};
    var basePrice=Number(p.basePrice!==undefined?p.basePrice:p.price)||0;
    var stock=Number(p.stock)||99;
    var img=p.image||'';
    var delta=0,labels=[],skuSuffix='';
    Object.keys(activeSheetVars).forEach(function(gIdx){
      var v=activeSheetVars[gIdx];
      if(!v)return;
      delta+=Number(v.price||0);
      labels.push((v.groupName?v.groupName+': ':'')+v.label);
      if(v.image)img=v.image;
      if(v.stock!==undefined&&v.stock!==null&&!isNaN(Number(v.stock)))stock=Number(v.stock);
      skuSuffix+='__'+(v.groupName||gIdx)+'-'+v.label;
    });
    var unitPrice=Math.max(0,basePrice+delta);
    return {
      unitPrice:unitPrice,
      stock:stock,
      image:img,
      variant:labels.join(' • '),
      skuSuffix:skuSuffix
    };
  }

  function syncCartSheetUI(){
    if(!activeSheetProduct)return;
    var st=getSheetComputedState();
    if(activeSheetQty>st.stock)activeSheetQty=Math.max(1,st.stock);
    var th=$('#buiCsThumb'),ti=$('#buiCsTitle'),pr=$('#buiCsPrice'),sk=$('#buiCsStock'),mx=$('#buiCsMaxLabel'),qv=$('#buiCsQtyVal'),sub=$('#buiCsSubtotal'),subBtn=$('#buiCsSubmit');
    if(th)th.innerHTML=thumbHTML(st.image);
    if(ti)ti.textContent=activeSheetProduct.title||'Produk';
    if(pr)pr.textContent=st.unitPrice?money(st.unitPrice):'Gratis';
    if(sk)sk.textContent=st.stock>0?('STOK '+st.stock):'STOK HABIS';
    if(mx)mx.textContent='Maks. '+st.stock;
    if(qv)qv.textContent=activeSheetQty;
    if(sub)sub.textContent=money(st.unitPrice*activeSheetQty);
    if(subBtn)subBtn.disabled=st.stock<1;
  }

  function tryAdd(info){
    openAddToCartSheet(info);
  }
  function saveBookmark(item){
    if(item&&item.isProduct)return;
    var index=-1;bookmarks.forEach(function(x,i){if(sameId(x.id,item.id))index=i});
    if(index>=0){bookmarks.splice(index,1);showNotice('Removed from bookmarks')}else{bookmarks.unshift({id:item.id,url:item.url,title:item.title,image:item.image,label:item.label||''});showNotice('Added to bookmarks')}
    writeStore(BOOKMARK_KEY,bookmarks);renderSaved();
  }
  function isSaved(id){return bookmarks.some(function(x){return sameId(x.id,id)})}
  function cartQty(){return cart.reduce(function(n,x){return n+(Number(x.qty)||1)},0)}
  function cartTotal(){return cart.reduce(function(n,x){return n+(Number(x.price)||0)*(Number(x.qty)||1)},0)}

  function rowHTML(item,kind){
    var vBadge=(kind==='cart'&&item.variant)?' ['+item.variant+']':'';
    var nBadge=(kind==='cart'&&item.note)?' • Catatan: '+item.note:'';
    var meta=kind==='cart'?(money(item.price)+' x '+(item.qty||1)+vBadge+nBadge):(item.label?('in '+item.label):'Saved article');
    var attr=kind==='cart'?'data-remove-cart':'data-remove-bookmark';
    return '<div class="dd-row"><a class="dd-thumb" href="'+escapeHTML(item.url)+'">'+thumbHTML(item.image)+'</a><div class="dd-info"><a class="dd-title" href="'+escapeHTML(item.url)+'">'+escapeHTML(item.title)+'</a><div class="dd-meta">'+escapeHTML(meta)+'</div></div><button class="dd-del" type="button" '+attr+'="'+escapeHTML(item.id)+'" aria-label="Remove">'+SVG_TRASH+'</button></div>';
  }
  function renderSaved(){
    var q=cartQty();
    var el;
    if((el=$('#cartCount')))el.textContent=q;
    if((el=$('#mobCartCount')))el.textContent=q;
    if((el=$('#cartDropdownCount')))el.textContent=q+' items';
    if((el=$('#bookmarkCount')))el.textContent=bookmarks.length;
    if((el=$('#mobBookmarkCount')))el.textContent=bookmarks.length;
    if((el=$('#bookmarkDropdownCount')))el.textContent=bookmarks.length+' saved';
    var c=$('#cartDropdownList'),b=$('#bookmarkDropdownList');
    if(c)c.innerHTML=cart.length?cart.map(function(x){return rowHTML(x,'cart')}).join(''):'<div class="dropdown-empty">Your cart is empty.</div>';
    if(b)b.innerHTML=bookmarks.length?bookmarks.map(function(x){return rowHTML(x,'bookmark')}).join(''):'<div class="dropdown-empty">No saved articles yet.</div>';
    $$('.post-card').forEach(function(card){
      var info=card._info||(card._info=getCardInfo(card));
      var price=$$('[data-price-display]',card),stock=$('[data-stock-display]',card),add=$('.add-cart-button',card),mark=$('.bookmark-card-button',card);
      price.forEach(function(p){p.textContent=priceText(info)});
      if(stock)applyStockBadge(card,info);
      if(add)add.classList.toggle('hidden',!info.isProduct);
      if(mark){var s=isSaved(info.id);mark.classList.toggle('is-saved',s);mark.setAttribute('aria-label',s?'Remove bookmark':'Save post')}
    });
    updatePostHeadButtons();
    $$('.js-cart-count').forEach(function(x){x.textContent=q});
    $$('.js-bm-count').forEach(function(x){x.textContent=bookmarks.length});
    renderPages();
  }

  /* ---------- /p/cart.html and /p/bookmarks.html ---------- */
  function mountRoot(id,path){
    var root=document.getElementById(id);
    if(root)return root;
    if(location.pathname!==path)return null;
    var main=$('#main-content');if(!main)return null;
    main.innerHTML='<div id="'+id+'"></div>';
    return document.getElementById(id);
  }
  function bareWrap(root){var art=root.closest?root.closest('.blog-post'):null;if(art)art.classList.add('is-bare')}
  function cartHTML(root){
    var wa=(root.getAttribute('data-whatsapp')||kvConfig['whatsapp']||'').replace(/\D/g,'');
    var q=cartQty();
    var head='<div class="eyebrow">YOUR SELECTION / '+('00'+q).slice(-3)+'</div><h1 class="page-title">YOUR <mark>CART.</mark></h1>';
    if(!cart.length)return '<section class="cart-page">'+head+'<div class="cart-empty"><h3>Keranjang masih kosong.</h3><p>Tambahkan produk dari halaman produk, lalu kembali ke sini.</p><a class="button" href="/search/label/Product"><span>LIHAT PRODUK</span>'+SVG_ARROW_UP_RIGHT+'</a></div></section>';
    var rows=cart.map(function(x){
      var qty=x.qty||1,line=(Number(x.price)||0)*qty;
      return '<div class="cart-row"><a href="'+escapeHTML(x.url)+'">'+thumbHTML(x.image)+'</a>'+
        '<div><h3><a href="'+escapeHTML(x.url)+'">'+escapeHTML(x.title)+'</a></h3><p class="unit">'+(x.variant?'<b>'+escapeHTML(x.variant)+'</b> • ':'')+money(x.price)+' / item'+(x.stock?' - stock '+x.stock:'')+(x.note?'<br/><i>Catatan: '+escapeHTML(x.note)+'</i>':'')+'</p>'+
        '<div class="qty"><button type="button" class="qty-minus" data-id="'+escapeHTML(x.id)+'" aria-label="Decrease">-</button><span>'+qty+'</span><button type="button" class="qty-plus" data-id="'+escapeHTML(x.id)+'" aria-label="Increase">+</button></div><br/>'+
        '<button class="remove-saved" type="button" data-remove-cart="'+escapeHTML(x.id)+'">'+SVG_TRASH+'<span>REMOVE</span></button></div>'+
        '<div class="line-total">'+money(line)+'</div></div>';
    }).join('');
    var waBtn=wa?'<a class="button dark" id="cartWhatsapp" href="#" target="_blank" rel="noopener"><span>ORDER VIA WHATSAPP</span>'+SVG_ARROW_UP_RIGHT+'</a>':'';
    return '<section class="cart-page">'+head+'<div class="cart-grid"><div class="cart-items">'+rows+'</div>'+
      '<aside class="cart-summary"><div class="row"><span>Items</span><span>'+q+'</span></div><div class="row"><span>Estimated total</span></div><div class="total">'+money(cartTotal())+'</div>'+waBtn+
      '<button class="button" id="copyCartSummary" type="button">COPY ORDER SUMMARY</button><button class="button pink" id="clearCart" type="button">CLEAR CART</button></aside></div>'+
      '<p class="cart-note">Data keranjang disimpan di browser ini saja (localStorage). Tema ini tidak memproses pembayaran maupun mengurangi stok.</p></section>';
  }
  function orderText(){
    return 'Halo, saya mau pesan:\n'+cart.map(function(x){return '- '+x.title+(x.variant?' ('+x.variant+')':'')+' x'+(x.qty||1)+' - '+money((Number(x.price)||0)*(x.qty||1))+(x.note?'\n  Catatan: '+x.note:'')}).join('\n')+'\nTotal: '+money(cartTotal());
  }
  function renderPages(){
    var cr=mountRoot('bui-cart','/p/cart.html');
    if(cr){
      bareWrap(cr);cr.innerHTML=cartHTML(cr);
      var wa=(cr.getAttribute('data-whatsapp')||kvConfig['whatsapp']||'').replace(/\D/g,''),w=$('#cartWhatsapp',cr);
      if(w&&wa)w.href='https://wa.me/'+wa+'?text='+encodeURIComponent(orderText());
    }
    var br=mountRoot('bui-bookmarks','/p/bookmarks.html');
    if(br){
      bareWrap(br);
      var head='<div class="eyebrow">YOUR READING LIST</div><h1 class="page-title">SAVED <mark>ARTICLES.</mark></h1>';
      br.innerHTML='<section class="bookmark-page">'+head+(bookmarks.length?bookmarks.map(function(x){
        return '<div class="saved-row"><a href="'+escapeHTML(x.url)+'">'+thumbHTML(x.image)+'</a><div><h3><a href="'+escapeHTML(x.url)+'">'+escapeHTML(x.title)+'</a></h3><p>BOOKMARKED ARTICLE</p></div><button class="remove-saved" data-remove-bookmark="'+escapeHTML(x.id)+'" type="button">'+SVG_TRASH+'<span>REMOVE</span></button></div>';
      }).join(''):'<div class="cart-empty"><h3>Belum ada bookmark.</h3><p>Simpan artikel untuk melihatnya di sini.</p><a class="button" href="/search"><span>JELAJAHI POSTINGAN</span>'+SVG_ARROW_UP_RIGHT+'</a></div>')+'</section>';
    }
  }
  function initSavedPageActions(){
    document.addEventListener('click',function(e){
      var t=e.target;if(!t.closest)return;
      var rc=t.closest('[data-remove-cart]');
      if(rc){var id=rc.getAttribute('data-remove-cart');cart=cart.filter(function(x){return !sameId(x.id,id)});writeStore(CART_KEY,cart);renderSaved();return}
      var rb=t.closest('[data-remove-bookmark]');
      if(rb){var id2=rb.getAttribute('data-remove-bookmark');bookmarks=bookmarks.filter(function(x){return !sameId(x.id,id2)});writeStore(BOOKMARK_KEY,bookmarks);renderSaved();return}
      var plus=t.closest('.qty-plus'),minus=t.closest('.qty-minus');
      if(plus||minus){
        var pid=(plus||minus).getAttribute('data-id');
        var item=cart.filter(function(x){return sameId(x.id,pid)})[0];
        if(item){var max=Number(item.stock)||99;var next=(item.qty||1)+(plus?1:-1);if(next>max){showNotice('Max stock reached')}item.qty=Math.max(1,Math.min(max,next));writeStore(CART_KEY,cart);renderSaved()}
        return;
      }
      if(t.closest('#clearCart')){if(confirm('Kosongkan keranjang?')){cart=[];writeStore(CART_KEY,cart);renderSaved()}return}
      if(t.closest('#copyCartSummary')){
        var text=orderText();
        if(navigator.clipboard&&navigator.clipboard.writeText)navigator.clipboard.writeText(text).then(function(){showNotice('Order summary copied')}).catch(function(){showNotice('Copy failed')});
        else showNotice('Copy is not supported here');
      }
    });
  }

  /* ---------- Cards + Article ---------- */
  function initCards(){
    $$('.post-card').forEach(function(card){
      var info=getCardInfo(card);card._info=info;
      if(info.isProduct)knownProducts[String(info.id)]=info;
      var productPrice=$('.product-price',card),tier=$('.tier-pill',card),pc=productCfg();
      if(productPrice)productPrice.textContent=priceText(info);
      if(tier){tier.textContent=info.price?(pc['tier-premium']||'PREMIUM'):(pc['tier-free']||'GRATIS');tier.classList.toggle('is-free',!info.price)}
      if(info.isProduct){
        applyStockBadge(card,info);buildCardButtons(card,info);
        var det=$('.card-read-link span',card);if(det&&pc['detail-button'])det.textContent=pc['detail-button'];
      }
      var add=$('.add-cart-button',card),mark=$('.bookmark-card-button',card);
      if(add)add.addEventListener('click',function(){tryAdd(card._info)});
      if(mark)mark.addEventListener('click',function(){saveBookmark(card._info)});
    });
  }
  /* ---------- HERO ---------- */
  function heroType(){
    var advanced='';try{advanced=getComputedStyle(document.body).getPropertyValue('--bui-hero-order').trim()}catch(e){}
    var items=advanced?advanced.split(',').map(function(x){return x.trim().toLowerCase()}):$$('#heroZone .hero-order').map(function(i){return i.textContent.trim().toLowerCase()});
    var first=items[0]||'productpost';
    return first.indexOf('blog')!==-1?'blog':'product';
  }
  function feedJSON(path){
    return fetch(path,{credentials:'omit'}).then(function(r){if(!r.ok)throw new Error('feed');return r.json()}).then(function(j){return (j.feed&&j.feed.entry)||[]});
  }
  function bigImg(u){return u?u.replace(/\/s\d+(-[a-z]+)?\//,'/s900/').replace(/=s\d+(-[a-z]+)?(?=$|\?)/,'=s900'):''}
  function parseEntry(e){
    var link=(e.link||[]).filter(function(l){return l.rel==='alternate'})[0];
    var html=(e.content&&e.content.$t)||(e.summary&&e.summary.$t)||'';
    var doc=new DOMParser().parseFromString(html,'text/html');
    var m=readMeta(doc.body);
    var id=String((e.id&&e.id.$t)||'').split('post-').pop();
    var k=knownProducts[id];
    if(k&&!m.price){m.price=k.price;m.stock=k.stock}
    var imgEl=doc.querySelector('img');
    var img=(e.media$thumbnail&&e.media$thumbnail.url)||(imgEl?imgEl.getAttribute('src'):'')||(k?k.image:'');
    var text=(doc.body.textContent||'').replace(/\s+/g,' ').trim();
    var labels=(e.category||[]).map(function(c){return c.term});
    return {id:id,url:link?link.href:'#',title:(e.title&&e.title.$t)||'Untitled',image:bigImg(img),text:text.slice(0,200),words:text?text.split(' ').length:0,labels:labels,price:m.price,stock:m.stock,date:e.published?new Date(e.published.$t):null,isProduct:labels.indexOf('Product')!==-1};
  }
  function ticker(words){
    var one=words.map(function(w){return '<span>'+escapeHTML(w)+SVG_STAR+'</span>'}).join('');
    return '<div class="ticker" aria-hidden="true"><div class="ticker-track">'+one+one+one+one+'</div></div>';
  }
  function fmtDate(d){try{return d?d.toLocaleDateString('en-GB',{day:'2-digit',month:'short',year:'numeric'}):''}catch(e){return ''}}

  function pad2(n){return ('0'+n).slice(-2)}
  function minRead(words){return Math.max(1,Math.ceil((words||0)/200))}
  function heroKicker(title,href,linkText){
    return '<div class="hero-kicker"><h2><i></i>'+escapeHTML(title)+'</h2><a href="'+href+'"><span>'+escapeHTML(linkText)+'</span>'+SVG_ARROW_UP_RIGHT+'</a></div>';
  }
  function noThumb(){return '<div class="no-image">No Thumbnail</div>'}

  /* PRODUCT HERO: spotlight (blur background, tilted card, selector rail) */
  function renderProductHero(stage,list){
    var n=list.length,idx=0,timer=null,DUR=6500,reduce=window.matchMedia&&window.matchMedia('(prefers-reduced-motion: reduce)').matches;
    var prices=list.map(function(p){return p.price}).filter(function(x){return x>0});
    var inStock=list.filter(function(p){return p.price>0&&p.stock>0}).length;
    var min=prices.length?Math.min.apply(null,prices):0;
    stage.innerHTML=heroKicker('Available now','/search/label/Product','All products')+
      ticker(['New drop','In stock','Digital goods','Instant access','Made with intent'])+
      '<div class="ps" id="psRoot"><div class="ps-bg" id="psBg"></div><div class="ps-main"><div class="ps-text" id="psText"></div><div class="ps-visual" id="psVisual"></div></div>'+
      '<div class="ps-rail" id="psRail">'+list.map(function(p,i){
        return '<button class="ps-pill" type="button" data-i="'+i+'" aria-label="'+escapeHTML(p.title)+'"><span class="th">'+(p.image?lzImg(p.image,'','',160,160,true):noThumb())+'</span><span><strong>'+escapeHTML(p.title)+'</strong><small>'+(p.price?money(p.price):'Detail')+'</small></span><span class="bar"></span></button>';
      }).join('')+'</div></div>';
    var root=$('#psRoot',stage),bg=$('#psBg',stage),text=$('#psText',stage),visual=$('#psVisual',stage),rail=$('#psRail',stage),pills=$$('.ps-pill',stage);
    root.style.setProperty('--ph-dur',(DUR/1000)+'s');
    function schedule(){clearTimeout(timer);if(n<2||reduce)return;timer=setTimeout(function(){if(document.hidden){schedule();return}paint((idx+1)%n,true)},DUR)}
    function paint(i,anim){
      idx=(i+n)%n;var p=list[idx];
      var sticker=!p.price?'NEW<br/>DROP':(p.stock>0?'IN<br/>STOCK':'SOLD<br/>OUT');
      var cats=p.labels.filter(function(l){return l!=='Product'}).slice(0,2);
      bg.style.backgroundImage=p.image?'url("'+p.image.replace(/"/g,'')+'")':'none';
      var status=p.price?(p.stock>0?'<span class="ps-chip ok">In stock: '+p.stock+'</span>':'<span class="ps-chip hot">Sold out</span>'):'<span class="ps-chip hot">New drop</span>';
      text.innerHTML='<div class="ps-idx">'+pad2(idx+1)+'</div>'+
        '<div class="ps-chips">'+status+cats.map(function(c){return '<span class="ps-chip">'+escapeHTML(c)+'</span>'}).join('')+'<span class="ps-chip">'+minRead(p.words)+' min view</span></div>'+
        '<h2 class="ps-title">'+escapeHTML(p.title)+'</h2>'+
        '<p class="ps-desc">'+escapeHTML(p.text||'Explore this product.')+'</p>'+
        (p.price?'<div class="ps-priceRow"><span class="ps-price">'+money(p.price)+'</span></div>':'')+
        '<div class="ps-cta"><a class="button dark" href="'+escapeHTML(p.url)+'"><span>DETAIL PRODUCT</span>'+SVG_ARROW_UP_RIGHT+'</a>'+
        (p.price&&p.stock>0?'<button class="button ghost" type="button" data-add="'+idx+'">'+SVG_CART+'<span>ADD TO CART</span></button>':'')+'</div>'+
        '<div class="ps-meta"><span>'+n+' products</span><span>from '+(min?money(min):'-')+'</span><span>'+inStock+' in stock</span></div>';
      visual.innerHTML='<a class="ps-card" href="'+escapeHTML(p.url)+'" aria-label="'+escapeHTML(p.title)+'">'+(p.image?'<img src="'+escapeHTML(resizeUrl(p.image,640,false))+'" alt="" decoding="async" fetchpriority="high"/>':noThumb())+'</a>'+
        '<span class="ps-sticker">'+sticker+'</span>'+
        '<div class="ps-controls"><button type="button" data-ps="prev" aria-label="Previous product">'+SVG_ARROW_LEFT+'</button><button type="button" data-ps="next" aria-label="Next product">'+SVG_ARROW_RIGHT+'</button></div>';
      pills.forEach(function(t,k){t.classList.remove('active');if(k===idx){void t.offsetWidth;t.classList.add('active')}});
      var act=pills[idx];
      if(act&&rail&&rail.scrollTo){rail.scrollTo({left:Math.max(0,act.offsetLeft-rail.clientWidth/2+act.clientWidth/2),behavior:'smooth'})}
      if(anim){root.classList.remove('swap');void root.offsetWidth;root.classList.add('swap')}
      schedule();
    }
    paint(0,false);
    stage.addEventListener('click',function(e){
      var t=e.target.closest?e.target.closest('[data-ps],[data-i],[data-add]'):null;if(!t)return;
      if(t.hasAttribute('data-ps')){paint(idx+(t.getAttribute('data-ps')==='next'?1:-1),true);return}
      if(t.hasAttribute('data-i')){paint(Number(t.getAttribute('data-i')),true);return}
      if(t.hasAttribute('data-add')){var p=list[Number(t.getAttribute('data-add'))];tryAdd({id:p.id,url:p.url,title:p.title,image:p.image,price:p.price,stock:p.stock})}
    });
    root.addEventListener('pointerenter',function(){clearTimeout(timer);root.classList.add('paused')});
    root.addEventListener('pointerleave',function(){root.classList.remove('paused');paint(idx,false)});
    var sx=0;root.addEventListener('touchstart',function(e){sx=e.touches[0].clientX},{passive:true});
    root.addEventListener('touchend',function(e){var dx=e.changedTouches[0].clientX-sx;if(Math.abs(dx)>60)paint(idx+(dx<0?1:-1),true)},{passive:true});
  }

  /* BLOG HERO: magazine bento (lead + 2 cards + trending + topics) */
  function renderBlogHero(stage,list){
    var lead=list[0],side=list.slice(1,3),trend=list.slice(3,7);
    var seen={},topics=[];
    list.forEach(function(p){p.labels.forEach(function(l){if(l!=='Product'&&!seen[l]){seen[l]=1;topics.push(l)}})});
    var now=lead.date||new Date();
    function card(p){
      return '<a class="bh-card" href="'+escapeHTML(p.url)+'"><div class="bh-card-img">'+(p.image?lzImg(p.image,'','',480,300,true):noThumb())+'</div>'+
        '<div class="bh-card-body"><span class="bh-tag">'+escapeHTML(p.labels[0]||'Post')+'</span><h4>'+escapeHTML(p.title)+'</h4><small>'+escapeHTML(fmtDate(p.date))+' / '+minRead(p.words)+' min read</small></div></a>';
    }
    stage.innerHTML=heroKicker('Fresh from the blog','/search','All posts')+
      ticker(['Latest stories','Fresh posts','Read','Save','Share','Stay curious'])+
      '<div class="bh"><a class="bh-lead" href="'+escapeHTML(lead.url)+'"><div class="bh-lead-img">'+(lead.image?'<img src="'+escapeHTML(resizeUrl(lead.image,800,false))+'" alt="" decoding="async" fetchpriority="high"/>':noThumb())+'</div>'+
      '<div class="bh-flag"><span>Featured</span><span class="alt">'+pad2(now.getMonth()+1)+'/'+now.getFullYear()+'</span></div><span class="bh-big">01</span>'+
      '<div class="bh-lead-body"><h3>'+escapeHTML(lead.title)+'</h3><p>'+escapeHTML(lead.text)+'</p><div class="bh-meta"><span class="readbar">READ STORY '+SVG_ARROW_RIGHT+'</span><span>'+escapeHTML(lead.labels[0]||'Post')+'</span><span>'+minRead(lead.words)+' min read</span></div></div></a>'+
      side.map(card).join('')+
      (trend.length?'<div class="bh-trend"><div class="bh-trend-head"><span>Trending</span><b>Top '+trend.length+'</b></div>'+trend.map(function(p,i){return '<a href="'+escapeHTML(p.url)+'"><i>'+pad2(i+1)+'</i><strong>'+escapeHTML(p.title)+'</strong></a>'}).join('')+'</div>':'')+
      (topics.length?'<div class="bh-topics"><span>Topics</span>'+topics.slice(0,8).map(function(t){return '<a href="/search/label/'+encodeURIComponent(t)+'">'+escapeHTML(t)+'</a>'}).join('')+'</div>':'')+
      '</div>';
  }

  function initHero(){
    var stage=$('#heroStage');
    var type=heroType();
    document.body.setAttribute('data-hero-type',type);
    if(!stage){return}
    var path=type==='product'?'/feeds/posts/default/-/Product?alt=json&max-results=8':'/feeds/posts/default?alt=json&max-results=30';
    feedJSON(path).then(function(entries){
      var list=entries.map(parseEntry).filter(function(p){return type==='product'?true:!p.isProduct});
      if(!list.length && entries.length){
        list=entries.map(parseEntry);
      }
      list=list.slice(0,type==='product'?8:6);
      if(!list.length){
        stage.innerHTML='<div class="hero-empty">'+(type==='product'?'Belum ada produk. Beri label <b>Product</b> pada postingan produk.':'Belum ada postingan blog.')+'</div>';
        return;
      }
      if(type==='product'&&list.some(function(p){return p.isProduct}))renderProductHero(stage,list);
      else renderBlogHero(stage,list);
    }).catch(function(){
      stage.innerHTML='<div class="hero-empty">Hero tidak dapat dimuat. <a href="/search">Lihat semua postingan</a></div>';
    });
    filterBelow(type);
  }
  function filterBelow(type){
    var title=$('#sectionHeadingTitle'),sub=$('#sectionHeadingSubText');
    var showProduct=type==='blog';
    var cards=$$('.post-card');
    var visible=0;
    cards.forEach(function(card){
      var isP=card.classList.contains('is-product');
      var hide=showProduct?!isP:isP;
      card.classList.toggle('is-hidden',hide);
      if(!hide)visible++;
    });
    if(!visible && cards.length){
      cards.forEach(function(card){card.classList.remove('is-hidden')});
      if(title)title.innerHTML='LATEST <mark>POSTS</mark>';
      if(sub)sub.textContent='READ / SAVE / SHARE';
    }else{
      if(title)title.innerHTML=showProduct?'AVAILABLE <mark>PRODUCTS</mark>':'LATEST <mark>POSTS</mark>';
      if(sub)sub.textContent=showProduct?'PICK / ADD / CHECKOUT':'READ / SAVE / SHARE';
    }    markProductGrid();
  }

  /* ---------- Theme, Color Accent, Font Size ("Aa"), Dropdowns, Mobile Menu ---------- */
  function initThemeAndSettings(){
    /* Dark / Light Mode */
    var stored='';try{stored=localStorage.getItem(THEME_KEY)||''}catch(e){}
    var prefers=window.matchMedia&&window.matchMedia('(prefers-color-scheme: dark)').matches;
    var theme=stored||(prefers?'dark':'light');
    document.documentElement.setAttribute('data-theme',theme);
    var btn=$('#themeToggle');
    function icon(next){return next==='dark'?'<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round"><path d="M20.5 14.5A8.5 8.5 0 0 1 9.5 3.5 8.5 8.5 0 1 0 20.5 14.5Z"/></svg>':'<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round"><circle cx="12" cy="12" r="4"/><path d="M12 2v2M12 20v2M4.93 4.93l1.42 1.42m11.3 11.3 1.42 1.42M2 12h2m16 0h2M4.93 19.07l1.42-1.42m11.3-11.3 1.42-1.42"/></svg>'}
    if(btn)btn.innerHTML=icon(theme);
    if(btn)btn.addEventListener('click',function(){
      var next=document.documentElement.getAttribute('data-theme')==='dark'?'light':'dark';
      document.documentElement.setAttribute('data-theme',next);
      try{localStorage.setItem(THEME_KEY,next)}catch(e){}
      btn.innerHTML=icon(next);
    });

    /* Color Swatches */
    var savedColor='lime';try{savedColor=localStorage.getItem(COLOR_KEY)||'lime'}catch(e){}
    function applyColor(c){
      document.documentElement.setAttribute('data-color',c);
      $$('#colorSwatches .color-swatch').forEach(function(sw){
        sw.classList.toggle('active',sw.getAttribute('data-color')===c);
      });
    }
    applyColor(savedColor);
    $$('#colorSwatches .color-swatch').forEach(function(sw){
      sw.addEventListener('click',function(){
        var c=sw.getAttribute('data-color');
        applyColor(c);
        try{localStorage.setItem(COLOR_KEY,c)}catch(e){}
      });
    });

    /* Font Size (Small, Medium, Large) */
    var savedSize='medium';try{savedSize=localStorage.getItem(FONTSIZE_KEY)||'medium'}catch(e){}
    function applyFontSize(sz){
      document.documentElement.setAttribute('data-fontsize',sz);
      $$('#fontSizeControls .fontsize-btn').forEach(function(b){
        b.classList.toggle('active',b.getAttribute('data-size')===sz);
      });
    }
    applyFontSize(savedSize);
    $$('#fontSizeControls .fontsize-btn').forEach(function(b){
      b.addEventListener('click',function(){
        var sz=b.getAttribute('data-size');
        applyFontSize(sz);
        try{localStorage.setItem(FONTSIZE_KEY,sz)}catch(e){}
      });
    });
  }

  function initDropdowns(){
    var backdrop=document.createElement('div');backdrop.className='sheet-backdrop';backdrop.id='sheetBackdrop';document.body.appendChild(backdrop);
    function closeAll(){
      $$('.dropdown-wrap').forEach(function(w){w.classList.remove('open');var b=$('.dropdown-toggle',w);if(b)b.setAttribute('aria-expanded','false')});
      backdrop.classList.remove('is-open');document.body.classList.remove('sheet-open');
    }
    function sync(){
      var sheet=$('.dropdown-wrap.open[data-sheet]');
      backdrop.classList.toggle('is-open',!!sheet);
      document.body.classList.toggle('sheet-open',!!sheet&&window.innerWidth<=680);
    }
    $$('.dropdown-toggle').forEach(function(btn){
      btn.addEventListener('click',function(e){
        e.stopPropagation();
        var wrap=btn.closest('.dropdown-wrap'),open=!wrap.classList.contains('open');
        closeAll();
        if(open){wrap.classList.add('open');btn.setAttribute('aria-expanded','true');sync()}
      });
    });
    document.addEventListener('click',function(e){
      var t=e.target;if(!t||!t.closest)return;
      if(t.closest('.dd-close')){closeAll();return}
      if(!t.closest('.dropdown-wrap'))closeAll();
    });
    backdrop.addEventListener('click',closeAll);
    document.addEventListener('keydown',function(e){if(e.key==='Escape')closeAll()});
  }

  function initMobileMenu(){
    var btn=$('#mobileMenuButton'),mobBtn=$('#mobMenuTrigger'),drawer=$('#leftDrawer'),backdrop=$('#drawerBackdrop'),close=$('#drawerClose');
    function setOpen(open){
      if(!drawer||!backdrop)return;
      drawer.classList.toggle('is-open',open);
      backdrop.classList.toggle('is-open',open);
      document.body.classList.toggle('drawer-open',open);
      drawer.setAttribute('aria-hidden',String(!open));
      if(btn)btn.setAttribute('aria-expanded',String(open));
      if(mobBtn)mobBtn.classList.toggle('active',open);
    }
    if(btn)btn.addEventListener('click',function(){setOpen(!drawer.classList.contains('is-open'))});
    if(mobBtn)mobBtn.addEventListener('click',function(){setOpen(!drawer.classList.contains('is-open'))});
    var mobSearch=$('#mobSearchTrigger');
    if(mobSearch)mobSearch.addEventListener('click',function(){setOpen(true);setTimeout(function(){var i=$('.drawer-search input');if(i)i.focus()},380)});
    if(close)close.addEventListener('click',function(){setOpen(false)});
    if(backdrop)backdrop.addEventListener('click',function(){setOpen(false)});
    document.addEventListener('keydown',function(e){if(e.key==='Escape')setOpen(false)});
    if(drawer){
      drawer.addEventListener('click',function(e){
        var link=e.target.closest('a[href]');
        if(link && link.getAttribute('href').indexOf('#style-')!==0){
          setOpen(false);
        }
      });
    }
  }

  var TR_LANGS=[['id','Indonesia'],['en','Inggris'],['ja','Jepang'],['ko','Korea'],['ar','Arab'],['es','Spanyol'],['fr','Prancis'],['de','Jerman'],['zh-CN','Mandarin']];
  function cookieGet(name){var m=document.cookie.match(new RegExp('(?:^|; )'+name+'=([^;]*)'));return m?decodeURIComponent(m[1]):''}
  function cookieSet(name,val,domain){document.cookie=name+'='+val+'; path=/; max-age=31536000'+(domain?'; domain='+domain:'')}
  function cookieDel(name,domain){document.cookie=name+'=; path=/; expires=Thu, 01 Jan 1970 00:00:00 GMT'+(domain?'; domain='+domain:'')}
  function translateCookie(val){
    var host=location.hostname,parts=host.split('.'),root=parts.length>2?parts.slice(-2).join('.'):host;
    if(!val){cookieDel('googtrans');cookieDel('googtrans',host);cookieDel('googtrans','.'+host);if(root!==host)cookieDel('googtrans','.'+root);return}
    cookieSet('googtrans',val);
    if(host.indexOf('.')!==-1)cookieSet('googtrans',val,'.'+host);
    if(root!==host)cookieDel('googtrans','.'+root);
  }
  function initTranslation(){
    try{readKVSettings()}catch(e){}
    var kv=kvConfig||{};
    var ORIG=String((kv&&kv['site-language'])||'id').trim().toLowerCase()||'id';
    var c=cookieGet('googtrans'),m=c.match(/[^\/]+$/),code=(m&&c)?m[0]:ORIG;
    if(code===ORIG)translateCookie(null);
    var langs=TR_LANGS.slice();
    $$('[data-lang-list]').forEach(function(box){
      box.innerHTML=langs.map(function(l){return '<button type="button" class="lang-btn'+(l[0]===code?' active':'')+'" data-google-lang="'+l[0]+'"><span>'+l[1]+'</span><small>'+l[0]+'</small></button>'}).join('');
    });
    document.addEventListener('click',function(e){
      var el=e.target.closest?e.target.closest('[data-google-lang]'):null;if(!el)return;
      var to=el.getAttribute('data-google-lang');
      if(to===ORIG)translateCookie(null);else translateCookie('/'+ORIG+'/'+to);
      window.location.reload();
    });
    if(code!==ORIG){
      window.TranslateWidgetIsLoaded=function(){
        if(window.google&&window.google.translate)new window.google.translate.TranslateElement({pageLanguage:ORIG,multilanguagePage:true});
      };
      var s=document.createElement('script');s.src='//translate.google.com/translate_a/element.js?cb=TranslateWidgetIsLoaded';s.async=true;document.head.appendChild(s);
    }
  }

  function upsertMeta(selector,attr,value){
    if(value===undefined||value===null||String(value).trim()==='')return;
    var el=$(selector);
    if(!el){el=document.createElement('meta');if(selector.indexOf('property=')!==-1)el.setAttribute('property',selector.match(/property=['\"]([^'\"]+)/)[1]);else if(selector.indexOf('name=')!==-1)el.setAttribute('name',selector.match(/name=['\"]([^'\"]+)/)[1]);document.head.appendChild(el)}
    el.setAttribute(attr,String(value).trim());
  }

  function initMetaSettings(){
    var title=kvConfig['site-title']||'';
    var description=kvConfig['description']||'';
    var keywords=kvConfig['keywords']||'';
    var author=kvConfig['author']||'';
    var image=kvConfig['og-image']||'';
    var color=kvConfig['theme-color']||'#d8ff3e';
    var robots=kvConfig['robots']||'index,follow';
    var locale=kvConfig['og-locale']||'id_ID';
    var twitter=kvConfig['twitter-handle']||'';
    if(!title&&!description&&!keywords)return;
    var pageTitle=document.title||title;
    var fullTitle=(!title||pageTitle.toLowerCase().indexOf(title.toLowerCase())!==-1)?pageTitle:(pageTitle+' | '+title);
    document.title=fullTitle;
    var descEl=document.querySelector('meta[name="description"]');
    upsertMeta('meta[name="description"]','content',description||(descEl?descEl.content:''));
    upsertMeta('meta[name="keywords"]','content',keywords);
    upsertMeta('meta[name="author"]','content',author);
    upsertMeta('meta[name="robots"]','content',robots);
    upsertMeta('meta[name="theme-color"]','content',color);
    upsertMeta('meta[property="og:title"]','content',fullTitle);
    upsertMeta('meta[property="og:description"]','content',description);
    upsertMeta('meta[property="og:url"]','content',location.href);
    upsertMeta('meta[property="og:type"]','content',document.body.getAttribute('data-page-type')==='item'?'article':'website');
    upsertMeta('meta[property="og:locale"]','content',locale);
    upsertMeta('meta[name="twitter:title"]','content',fullTitle);
    upsertMeta('meta[name="twitter:description"]','content',description);
    upsertMeta('meta[name="twitter:card"]','content',image?'summary_large_image':'summary');
    if(image){upsertMeta('meta[property="og:image"]','content',image);upsertMeta('meta[name="twitter:image"]','content',image)}
    if(twitter){upsertMeta('meta[name="twitter:site"]','content',twitter)}
  }

  function initObserver(){
    if(!('IntersectionObserver' in window))return;
    var observer=new IntersectionObserver(function(entries){
      entries.forEach(function(e){
        if(e.isIntersecting){
          e.target.style.animationDelay=Math.min(Array.prototype.indexOf.call(e.target.parentNode.children,e.target)*70,350)+'ms';
          observer.unobserve(e.target);
        }
      });
    },{threshold:.08});
    $$('.post-card').forEach(function(card){observer.observe(card)});
  }

  /* ---------- Layout Options (TextList "Key: Value") ---------- */
  function readOpts(sel){
    var o={};
    $$(sel+' .bui-opt').forEach(function(el){
      var t=String(el.textContent||'').trim(),i=t.indexOf(':');
      if(i<1)return;
      o[t.slice(0,i).trim().toLowerCase()]=t.slice(i+1).trim();
    });
    return o;
  }
  function pick(v,list,def){v=String(v||'').toLowerCase().trim();return list.indexOf(v)!==-1?v:def}

  /* ---------- Header: sticky / style / width / shrink / progress ---------- */
  function initHeaderOptions(){
    var o=readOpts('.bui-opts[data-opts="header"]'),b=document.body,hdr=$('#siteHeader');
    if(!hdr)return;
    var cs={};try{var st=getComputedStyle(b);['sticky','style','width','shrink','progress','shadow'].forEach(function(k){cs[k]=parseInt(st.getPropertyValue('--bui-header-'+k),10)})}catch(e){}
    var sticky=({1:'on',2:'off',3:'smart'})[cs.sticky]||pick(o.sticky,['on','off','smart'],'on');
    b.setAttribute('data-hd-sticky',sticky);
    b.setAttribute('data-hd-style',({1:'solid',2:'glass',3:'floating',4:'transparent',5:'accent'})[cs.style]||pick(o.style,['solid','glass','floating','transparent','accent'],'solid'));
    b.setAttribute('data-hd-width',({1:'boxed',2:'full'})[cs.width]||pick(o.width,['boxed','full'],'boxed'));
    b.setAttribute('data-hd-shrink',({1:'on',2:'off'})[cs.shrink]||pick(o.shrink,['on','off'],'off'));
    b.setAttribute('data-hd-progress',({1:'on',2:'off'})[cs.progress]||pick(o.progress,['on','off'],'on'));
    b.setAttribute('data-hd-shadow',({1:'hard',2:'soft',3:'none'})[cs.shadow]||pick(o.shadow,['hard','soft','none'],'hard'));
    var bar=$('#readProgress'),lastY=window.pageYOffset||0,ticking=false;
    function update(){
      var y=window.pageYOffset||0;
      hdr.classList.toggle('scrolled',y>10);
      if(sticky==='smart'){
        if(y>lastY+8&&y>140)hdr.classList.add('is-hidden');
        else if(y<lastY-8||y<60)hdr.classList.remove('is-hidden');
      }
      if(bar&&document.body.classList.contains('item-view')){
        var max=docMax();
        bar.style.width=(max>0?Math.min(100,Math.max(0,y/max*100)):0)+'%';
      }
      lastY=y;ticking=false;
    }
    window.addEventListener('scroll',function(){if(!ticking){ticking=true;window.requestAnimationFrame(update)}},{passive:true});
    update();
  }

  /* ---------- Mobile bottom menu: style / labels / items / auto-hide ---------- */
  function mobItemTokens(){
    var list=$$('.bui-mobitem').map(function(el){return String(el.textContent||'').trim()}).filter(Boolean);
    return list.length?list:['home','menu','shop','saved','cart'];
  }
  function initBackTop(){
    var btn=$('#backTop');if(!btn)return;
    var o=readOpts('.bui-opts[data-opts="mobile"]'),backtopNum=1;try{backtopNum=parseInt(getComputedStyle(document.body).getPropertyValue('--bui-mobile-menu-backtop'),10)}catch(e){}
    if(backtopNum===2||(!backtopNum&&pick(o.backtotop,['on','off'],'on')==='off')){btn.classList.add('off');return}
    var ticking=false;
    function update(){
      var show=(window.pageYOffset||0)>420;
      btn.classList.toggle('show',show);
      document.body.classList.toggle('has-top',show);
      ticking=false;
    }
    window.addEventListener('scroll',function(){if(!ticking){ticking=true;window.requestAnimationFrame(update)}},{passive:true});
    btn.addEventListener('click',function(){window.scrollTo({top:0,behavior:'smooth'})});
    update();
  }
  function moveLabelDesc(){
    var card=$('.label-desc-card'),slot=$('#labelDescSlot');
    if(card&&slot)slot.appendChild(card);
  }
  function markProductGrid(){
    var grid=$('#postGrid');if(!grid)return;
    var cards=$$('.post-card',grid).filter(function(c){return !c.classList.contains('is-hidden')});
    var all=cards.length>0&&cards.every(function(c){return c.classList.contains('is-product')});
    grid.classList.toggle('grid-products',all);
  }

  function initMobileNav(){
    var nav=$('#mobileBottomNav');if(!nav)return;
    var o=readOpts('.bui-opts[data-opts="mobile"]'),b=document.body;
    var cssSettings={};
    try{var computed=getComputedStyle(document.body);['style','labels','autohide','backtop'].forEach(function(k){cssSettings[k]=computed.getPropertyValue('--bui-mobile-menu-'+k).trim()})}catch(e){}
    var designerStyleNum=parseInt(cssSettings.style,10),labelsNum=parseInt(cssSettings.labels,10),autoNum=parseInt(cssSettings.autohide,10),topNum=parseInt(cssSettings.backtop,10);
    b.setAttribute('data-mob-style',['classic','floating','pill','dock','tiles','minimal','glass','tabs','notch','slab'][(designerStyleNum||1)-1]||'classic');
    var cardStyleNum=parseInt(getComputedStyle(b).getPropertyValue('--bui-card-style'),10);b.setAttribute('data-bui-card-style',cardStyleNum===2?'square':'rounded');
    b.setAttribute('data-mob-labels',labelsNum===2?'off':'on');
    var map={};$$('.mob-nav-btn',nav).forEach(function(el){map[el.getAttribute('data-item')]=el;el.classList.add('is-hidden-item')});
    var alias={bookmark:'saved',bookmarks:'saved',save:'saved',keranjang:'cart',toko:'shop',produk:'shop',cari:'search',beranda:'home',atas:'top'};
    var gItems=parseIconItems('.bui-mob-item');
    if(!gItems.length)gItems=mobItemTokens().map(function(t){return {label:t,icon:'',link:''}});
    gItems.forEach(function(it,i){
      var k=String(it.label||'').trim().toLowerCase();k=alias[k]||k;
      if(map[k]){var el=map[k];el.classList.remove('is-hidden-item');if(it.link&&el.tagName==='A')el.setAttribute('href',it.link);nav.appendChild(el);return}
      var a=document.createElement('a');a.className='mob-nav-btn';a.setAttribute('data-item','custom-'+i);a.href=it.link||'#';a.setAttribute('aria-label',it.label);
      if(isExt(it.link)){a.target='_blank';a.rel='noopener'}
      a.innerHTML=iconSVG(it.icon||it.label)+'<span class="mob-label"></span>';
      a.lastChild.textContent=it.label;
      if(it.link&&it.link.charAt(0)==='/'&&location.pathname===it.link)a.classList.add('active');
      nav.appendChild(a);map['custom-'+i]=a;
    });
    var p=location.pathname,home=b.getAttribute('data-homepage')==='true';
    if(map.home&&home)map.home.classList.add('active');
    if(map.shop&&p.indexOf('/search/label/Product')===0)map.shop.classList.add('active');
    if(map.saved&&p==='/p/bookmarks.html')map.saved.classList.add('active');
    var vis=$$('.mob-nav-btn',nav).filter(function(x){return !x.classList.contains('is-hidden-item')});
    vis.forEach(function(x){x.classList.remove('is-center')});
    if(vis.length>=3&&vis.length%2===1)vis[(vis.length-1)/2].classList.add('is-center');
    if(map.cart&&p==='/p/cart.html')map.cart.classList.add('active');
    if(map.top)map.top.addEventListener('click',function(){window.scrollTo({top:0,behavior:'smooth'})});
    if(topNum===2&&map.top)map.top.classList.add('is-hidden-item');
    if((autoNum===2)||(autoNum!==1&&pick(o.autohide,['on','off'],'off')==='on')){
      var last=window.pageYOffset||0;
      window.addEventListener('scroll',function(){
        var y=window.pageYOffset||0;
        if(y>last+8&&y>160)nav.classList.add('is-hidden');
        else if(y<last-8)nav.classList.remove('is-hidden');
        last=y;
      },{passive:true});
    }
    var shrinkNum=1;try{shrinkNum=parseInt(getComputedStyle(b).getPropertyValue('--bui-mobile-menu-shrink'),10)}catch(e){}
    b.setAttribute('data-mob-shrink',shrinkNum===2?'on':'off');
    window.addEventListener('scroll',function(){
      var y=window.pageYOffset||0;
      nav.classList.toggle('is-shrunk',y>80);
      var pBar=$('#postMobileActions');
      if(pBar)pBar.classList.toggle('is-shrunk',y>80);
    },{passive:true});
    if(b.getAttribute('data-homepage')==='true'){var homeCart=$('[data-item="cart"]',nav),homeSaved=$('[data-item="saved"]',nav);if(homeCart)homeCart.classList.add('is-hidden-item');if(homeSaved)homeSaved.classList.add('is-hidden-item')}

  }

  /* ---------- Product tabs (.bTabs) ---------- */
  function initTabs(){
    $$('.bTabs').forEach(function(box){
      var btns=$$('.bTabs-nav button',box),panels=$$('.bTabs-panel',box);
      function go(i){
        btns.forEach(function(x,k){x.classList.toggle('active',k===i)});
        panels.forEach(function(x,k){x.classList.toggle('active',k===i)});
      }
      btns.forEach(function(btn,i){btn.addEventListener('click',function(){go(i)})});
      go(0);
    });
  }

  /* ---------- Post page: header card (reading/viewing time, price, buttons) ---------- */
  function updatePostHeadButtons(){
    var btn=$('.phc-main-btn'),info=getArticleInfo();
    if(!btn||!info||info.isProduct)return;
    var s=isSaved(info.id);
    var lbl=s?'Tersimpan di bookmark':'Simpan ke bookmark';
    btn.classList.toggle('is-saved',s);
    btn.setAttribute('aria-label',lbl);btn.setAttribute('title',lbl);
    btn.innerHTML=SVG_BOOKMARK+'<span class="visually-hidden">'+lbl+'</span>';
  }
  function initPostMobileActions(){
    var article=$('.blog-post.is-post');
    var bar=$('#postMobileActions'),trigger=$('#postShareTrigger'),sheet=$('#postShareSheet'),backdrop=$('#postShareBackdrop');
    if(!article||!bar||!trigger||!sheet||!backdrop)return;
    var isProductPost=article.classList.contains('is-product');
    var title=$('h1',article);title=title?title.textContent.trim():document.title;
    var url=location.href.split('#')[0];
    var count=$('.bui-comments-count',article);
    var countText=count?(count.textContent||'').trim():'';
    var countMatch=countText.match(/\d+/);
    var label=$('#postCommentsButtonLabel');
    if(label)label.textContent=(countMatch?countMatch[0]+' ':'')+'comments';
    var shareOptions=$('#postShareOptions');
    var encoded=encodeURIComponent(url),encTitle=encodeURIComponent(title);
    var socials=buildShareItems(url,title);
    if(shareOptions){
      shareOptions.innerHTML=socials.map(function(x){
        if(x.act)return '<button class="post-share-option" type="button" data-share-act="'+x.act+'">'+iconSVG(x.icon)+'<span>'+escapeHTML(x.name)+'</span></button>';
        return '<a class="post-share-option" href="'+escapeHTML(x.href)+'"'+(x.self?'':' target="_blank" rel="noopener noreferrer"')+'>'+iconSVG(x.icon)+'<span>'+escapeHTML(x.name)+'</span></a>';
      }).join('');
      shareOptions.addEventListener('click',function(e){
        var bt=e.target.closest?e.target.closest('[data-share-act]'):null;if(!bt)return;
        var a=bt.getAttribute('data-share-act');
        if(a==='print'){window.print()}
        else if(a==='native'&&navigator.share){navigator.share({title:title,url:location.href.split('#')[0]}).catch(function(){})}
      });
    }
    var input=$('#postShareLink');if(input)input.value=url;
    function setOpen(open){document.body.classList.toggle('post-share-open',open);sheet.setAttribute('aria-hidden',String(!open));backdrop.setAttribute('aria-hidden',String(!open));if(open){if(input)input.value=location.href.split('#')[0];var close=$('#postShareClose');if(close)close.focus()}else trigger.focus()}
    shareOpener=function(){setOpen(true)};
    trigger.addEventListener('click',function(){setOpen(true)});
    backdrop.addEventListener('click',function(){setOpen(false)});
    var close=$('#postShareClose');if(close)close.addEventListener('click',function(){setOpen(false)});
    var copy=$('#postShareCopy');if(copy)copy.addEventListener('click',function(){
      var value=input?input.value:url;
      function copied(){showNotice('Link berhasil disalin');copy.innerHTML=SVG_CHECK+'<span>Copied</span>';setTimeout(function(){copy.innerHTML=SVG_COPY+'<span>Copy link</span>'},1800)}
      if(navigator.clipboard&&navigator.clipboard.writeText){navigator.clipboard.writeText(value).then(copied).catch(function(){if(input){input.focus();input.select();try{document.execCommand('copy');copied()}catch(e){showNotice('Pilih dan salin link secara manual')}}})}
      else if(input){input.focus();input.select();try{document.execCommand('copy');copied()}catch(e){showNotice('Pilih dan salin link secara manual')}}
    });
    var comments=$('#postCommentsTrigger');if(comments)comments.addEventListener('click',function(){var target=$('#comments')||$('.bui-comments',article);if(target){target.scrollIntoView({behavior:'smooth',block:'start'});target.setAttribute('tabindex','-1');setTimeout(function(){try{target.focus({preventScroll:true})}catch(e){}},350)}else showNotice('Komentar tidak tersedia pada postingan ini')});
    var cartAddBtn=$('#postCartAddTrigger');
    if(cartAddBtn){
      cartAddBtn.addEventListener('click',function(){
        var info=getArticleInfo();
        if(info)tryAdd(info);
      });
    }

    /* Table of Contents Drawer (hanya untuk postingan non-Product) */
    var tocBtn=$('#postTocTrigger'),tocDrawer=$('#postTocDrawer'),tocBackdrop=$('#postTocBackdrop'),tocClose=$('#postTocClose'),tocBody=$('#postTocBody');
    if(isProductPost){
      if(tocBtn)tocBtn.remove();
    }else if(tocBtn&&tocDrawer&&tocBackdrop&&tocBody){
      var contentBox=$('.article-content',article);
      var headings=contentBox?$$('h2, h3, h4',contentBox).filter(function(h){return (h.textContent||'').trim().length>0}):[];
      if(!headings.length){
        tocBody.innerHTML='<p class="post-toc-empty">Tidak ada subjudul (Table of Contents) pada artikel ini.</p>';
      }else{
        var tree=[],currentH2=null;
        headings.forEach(function(h,idx){
          if(!h.id){
            var slug=String(h.textContent||'').trim().toLowerCase().replace(/[^a-z0-9]+/g,'-').replace(/^-|-$/g,'');
            h.id=slug?('toc-'+slug+'-'+(idx+1)):('section-'+(idx+1));
          }
          var tag=h.tagName.toUpperCase();
          var item={id:h.id,text:(h.textContent||'').trim(),children:[]};
          if(tag==='H2'||!currentH2){
            currentH2=item;
            tree.push(item);
          }else{
            currentH2.children.push(item);
          }
        });
        var html='<ol class="post-toc-list">';
        tree.forEach(function(node){
          html+='<li><a href="#'+escapeHTML(node.id)+'" data-toc-link="'+escapeHTML(node.id)+'"><span>'+escapeHTML(node.text)+'</span></a>';
          if(node.children.length){
            html+='<ol class="post-toc-sub">';
            node.children.forEach(function(sub){
              html+='<li><a href="#'+escapeHTML(sub.id)+'" data-toc-link="'+escapeHTML(sub.id)+'"><span>'+escapeHTML(sub.text)+'</span></a></li>';
            });
            html+='</ol>';
          }
          html+='</li>';
        });
        html+='</ol>';
        tocBody.innerHTML=html;
      }
      function setTocOpen(open){
        document.body.classList.toggle('post-toc-open',open);
        tocDrawer.setAttribute('aria-hidden',String(!open));
        tocBackdrop.setAttribute('aria-hidden',String(!open));
      }
      tocBtn.addEventListener('click',function(){
        setOpen(false);
        setTocOpen(!document.body.classList.contains('post-toc-open'));
      });
      tocBackdrop.addEventListener('click',function(){setTocOpen(false)});
      if(tocClose)tocClose.addEventListener('click',function(){setTocOpen(false)});
      tocBody.addEventListener('click',function(e){
        var a=e.target.closest?e.target.closest('a[data-toc-link]'):null;
        if(!a)return;
        e.preventDefault();
        var tid=a.getAttribute('data-toc-link');
        var targetEl=document.getElementById(tid);
        setTocOpen(false);
        if(targetEl){
          setTimeout(function(){targetEl.scrollIntoView({behavior:'smooth',block:'start'})},120);
        }
      });
    }

    document.addEventListener('keydown',function(e){
      if(e.key==='Escape'){
        setOpen(false);
        if(tocDrawer&&tocBackdrop){
          document.body.classList.remove('post-toc-open');
          tocDrawer.setAttribute('aria-hidden','true');
          tocBackdrop.setAttribute('aria-hidden','true');
        }
      }
    });

    /* Animasi scroll dock bar seperti di video: sembunyi saat scroll ke bawah di akhir halaman, muncul kembali saat scroll ke atas */
    var lastY=window.pageYOffset||0,ticking=false;
    function onScrollBar(){
      var y=window.pageYOffset||0;
      var max=docMax();
      var nearBottom=max>120 && y>=max-110;
      if(nearBottom||(y>lastY+10&&y>240)){
        bar.classList.add('is-hidden-bar');
      }else if(y<lastY-8||y<=160){
        bar.classList.remove('is-hidden-bar');
      }
      lastY=y;ticking=false;
    }
    window.addEventListener('scroll',function(){
      if(!ticking){ticking=true;window.requestAnimationFrame(onScrollBar)}
    },{passive:true});
  }

  function initProductVariations(){
    var oldMount=$('#buiProductVariants');if(oldMount)oldMount.remove();
    $$('.bui-var-box').forEach(function(el){el.remove()});
    var sheet=$('#buiCartSheet'),backdrop=$('#buiCartSheetBackdrop'),closeBtn=$('#buiCsClose');
    if(!sheet||sheet.getAttribute('data-init')==='1')return;
    sheet.setAttribute('data-init','1');
    if(closeBtn)closeBtn.addEventListener('click',closeAddToCartSheet);
    if(backdrop)backdrop.addEventListener('click',closeAddToCartSheet);
    document.addEventListener('keydown',function(e){if(e.key==='Escape')closeAddToCartSheet()});
    sheet.addEventListener('click',function(e){
      var optBtn=e.target.closest?e.target.closest('.bui-cs-opt'):null;
      if(optBtn&&!optBtn.disabled&&activeSheetProduct){
        var gIdx=Number(optBtn.getAttribute('data-gidx')),oIdx=Number(optBtn.getAttribute('data-oidx'));
        var grp=(activeSheetProduct.variations||[])[gIdx];
        var opt=grp&&grp.options?grp.options[oIdx]:null;
        if(opt){
          activeSheetVars[gIdx]={groupName:grp.name||('Variasi '+(gIdx+1)),label:opt.label,price:Number(opt.price||0),image:opt.image||'',stock:opt.stock};
          $$('.bui-cs-opt[data-gidx="'+gIdx+'"]',sheet).forEach(function(b){b.classList.toggle('active',b===optBtn)});
          var gVal=$('[data-cs-gval="'+gIdx+'"]',sheet);if(gVal)gVal.textContent=opt.label;
          syncCartSheetUI();
        }
        return;
      }
      if(e.target.closest('#buiCsQtyMinus')){
        activeSheetQty=Math.max(1,activeSheetQty-1);
        syncCartSheetUI();
        return;
      }
      if(e.target.closest('#buiCsQtyPlus')){
        var st=getSheetComputedState();
        if(activeSheetQty>=st.stock){showNotice('Maksimal stok tersedia: '+st.stock);return}
        activeSheetQty++;
        syncCartSheetUI();
        return;
      }
      if(e.target.closest('#buiCsSubmit')){
        if(!activeSheetProduct)return;
        var st2=getSheetComputedState();
        if(st2.stock<1){showNotice('Stok variasi ini habis.');return}
        var noteEl=$('#buiCsNote');
        var baseId=activeSheetProduct.baseId||activeSheetProduct.id;
        saveCart({
          id:baseId+(st2.skuSuffix||''),
          url:activeSheetProduct.url,
          title:activeSheetProduct.title,
          variant:st2.variant,
          note:noteEl?noteEl.value.trim():'',
          image:st2.image,
          price:st2.unitPrice,
          stock:st2.stock,
          qty:activeSheetQty
        });
        closeAddToCartSheet();
      }
    });
  }

  function initCookieConsent(){
    var banner=$('#buiCookieBanner');if(!banner)return;
    var cfg={};
    $$('#bui-cookie-settings .bui-cookie-kv').forEach(function(el){
      var k=String(el.getAttribute('data-key')||'').trim().toLowerCase();
      var v=String(el.getAttribute('data-val')||'').trim();
      if(k!=='policy-url' && v.indexOf('http://')===0 && v.indexOf('.')===-1)v=v.replace(/^http:\/\//,'');
      if(k)cfg[k]=v;
    });
    if(/^(off|no|false|0|hide)$/i.test(cfg['status']||'on'))return;
    var KEY='brutalism-ui-cookie-consent-v1';
    try{
      var saved=JSON.parse(localStorage.getItem(KEY)||'null');
      if(saved&&saved.exp&&Date.now()<saved.exp)return;
    }catch(e){}
    if(cfg['title']&&$('#buiCookieTitle'))$('#buiCookieTitle').textContent=cfg['title'];
    if(cfg['message']&&$('#buiCookieMsg'))$('#buiCookieMsg').textContent=cfg['message'];
    if(cfg['accept-text']&&$('#buiCookieAccept'))$('#buiCookieAccept').textContent=cfg['accept-text'];
    if(cfg['decline-text']&&$('#buiCookieDecline'))$('#buiCookieDecline').textContent=cfg['decline-text'];
    var pol=$('#buiCookiePolicy');
    if(pol){
      if(cfg['policy-text'])pol.textContent=cfg['policy-text'];
      if(cfg['policy-url']){
        var pu=cfg['policy-url'].replace(/^https?:\/\/(?=\/)/i,'');
        if(pu==='#')pol.style.display='none';else pol.href=pu;
      }
    }
    var days=Math.max(1,parseInt(cfg['expire-days'],10)||30);
    function dismiss(choice){
      banner.classList.remove('show');
      try{localStorage.setItem(KEY,JSON.stringify({choice:choice,exp:Date.now()+days*86400000}))}catch(e){}
    }
    var acc=$('#buiCookieAccept'),dec=$('#buiCookieDecline');
    if(acc)acc.addEventListener('click',function(){dismiss('accepted')});
    if(dec)dec.addEventListener('click',function(){dismiss('declined')});
    setTimeout(function(){banner.classList.add('show')},600);
  }

  function initPostHead(){
    var art=$('.blog-post.is-post'),head=art?$('.post-head-card',art):null;
    if(!art||!head)return;
    var info=getArticleInfo(),body=$('.article-content',art);
    if(!info||!body)return;
    var words=(body.innerText||body.textContent||'').trim().split(/\s+/).filter(Boolean).length;
    var imgs=$$('img',body).length;
    var minutes=info.isProduct?Math.max(1,Math.ceil(words/260+imgs*.25)):Math.max(1,Math.ceil(words/200+imgs*.1));
    var read=$('.phc-read',head);if(read)read.textContent=minutes+' menit';
    var main=$('.phc-main-btn',head),share=$('.phc-share-btn',head);
    if(info.isProduct){
      var pr=$('.phc-price dd',head);
      if(pr)pr.textContent=info.price?(money(info.price)+(info.stock>0?' / stok '+info.stock:' / habis')):'Hubungi penjual';
      if(main){
        main.innerHTML=SVG_CART+'<span class="visually-hidden">Tambah ke keranjang</span>';
        main.addEventListener('click',function(){tryAdd(info)});
      }
    }else if(main){
      main.addEventListener('click',function(){saveBookmark(info)});
      updatePostHeadButtons();
    }
    if(share){
      share.innerHTML=SVG_SHARE+'<span class="visually-hidden">Bagikan</span>';
      share.addEventListener('click',function(){
        if(shareOpener){shareOpener();return}
        var data={title:info.title,url:location.href};
        if(navigator.share){navigator.share(data).catch(function(){})}
        else if(navigator.clipboard&&navigator.clipboard.writeText){navigator.clipboard.writeText(location.href).then(function(){showNotice('Link disalin')})}
        else showNotice('Salin link dari address bar');
      });
    }
  }

  /* ---------- Drawer icons ---------- */
  function iconFor(name,href){
    var n=(String(name)+' '+String(href)).toLowerCase();
    var path=String(href||'').replace(/^https?:\/\/[^\/]+/,'');
    if(path==='/'||path===''||/home|beranda/.test(n))return SVG_HOME;
    if(/shop|product|produk|toko|store/.test(n))return SVG_BOX;
    if(/cart|keranjang/.test(n))return SVG_CART;
    if(/bookmark|saved|simpan/.test(n))return SVG_BOOKMARK;
    if(/about|tentang|info/.test(n))return SVG_INFO;
    if(/contact|kontak|mail|hubungi/.test(n))return SVG_MAIL;
    if(/categor|kategori|label|tag|tech|tutorial/.test(n))return SVG_TAG;
    return SVG_FOLDER;
  }
  function dIco(name,href){return '<span class="drawer-ico">'+iconFor(name,href)+'</span>'}
  function markCurrentLinks(){
    var p=location.pathname;
    $$('#leftDrawer a[href], .dq-tile').forEach(function(a){
      var ap=a.pathname;if(ap===undefined)return;
      var cur=(ap===p)&&(ap!=='/'||p==='/');
      if(a.classList.contains('dq-tile')||a.classList.contains('drawer-link'))a.classList.toggle('is-current',cur);
    });
    var logo=$('#drawerLogo'),t=document.title||'B';
    var bt=$('.drawer-brand-text strong');
    if(logo&&bt&&bt.textContent.trim())logo.textContent=bt.textContent.trim().charAt(0).toUpperCase();
  }

  /* ---------- v1.1.8 refinement: advanced styles, skeleton and live search ---------- */
  var _mxV=0,_mxT=0;
  function docMax(){var t=Date.now();if(t-_mxT>700){_mxV=(document.documentElement.scrollHeight||1)-window.innerHeight;_mxT=t}return _mxV}
  function initAdvancedStyleSettings(){
    var b=document.body,st=getComputedStyle(b);
    function num(name,def){var n=parseInt(st.getPropertyValue(name),10);return n||def}
    b.setAttribute('data-sidebar-style',String(Math.min(6,num('--bui-sidebar-style',1))));
    b.setAttribute('data-toc-style',String(Math.min(5,num('--bui-toc-style',1))));
    b.setAttribute('data-breadcrumb-style',String(Math.min(5,num('--bui-breadcrumb-style',2))));
    b.setAttribute('data-glass-variants',num('--bui-glass-variants',1)===2?'on':'off');
    b.setAttribute('data-glass-search',num('--bui-glass-search',2)===1?'off':'on');
    b.setAttribute('data-skeleton',num('--bui-skeleton',2)===1?'off':'on');
    b.setAttribute('data-post-layout',num('--bui-posts-layout',1)===2?'list':'grid');
    var foot=num('--bui-footer-style',3);b.setAttribute('data-footer-style',String(Math.min(7,foot)));
    var skeletonOn=b.getAttribute('data-skeleton')==='on';
    $$('.post-card').forEach(function(card){card.classList.remove('bui-skeleton-ready')});
    if(skeletonOn){
      var skReady=function(card){card.classList.add('bui-skeleton-ready')};
      $$('.post-card').forEach(function(card){
        var im=card.querySelector('.post-thumb img');
        if(!im||(im.complete&&!im.classList.contains('lazyload')&&im.naturalWidth>0)){skReady(card);return}
        im.addEventListener('load',function(){skReady(card)},{once:true});
        im.addEventListener('error',function(){skReady(card)},{once:true});
      });
      document.addEventListener('lazyloaded',function(e){var c=e.target&&e.target.closest?e.target.closest('.post-card'):null;if(c)skReady(c)});
      window.setTimeout(function(){$$('.post-card').forEach(skReady)},2500);
      window.setTimeout(function(){b.classList.add('bui-page-skeleton-ready')},150);
    }else{b.classList.add('bui-page-skeleton-ready')}
    function syncThumbRatio(img){var card=img.closest('.post-card'),thumb=img.closest('.post-thumb');if(!card||!thumb||card.classList.contains('is-product'))return;function apply(){if(img.naturalWidth>0&&img.naturalHeight>0)thumb.style.aspectRatio=img.naturalWidth+' / '+img.naturalHeight}if(img.complete)apply();else{img.addEventListener('load',apply,{once:true});img.addEventListener('error',function(){thumb.style.aspectRatio='16 / 9'},{once:true})}}
  }
  function initLiveSearch(){
    var panel=$('#buiLiveSearch'),back=$('#buiLiveSearchBackdrop'),input=$('#buiLiveSearchInput'),results=$('#buiLiveSearchResults'),status=$('#buiLiveSearchStatus'),close=$('#buiLiveSearchClose'),form=$('#buiLiveSearchForm');
    if(!panel||!input||!results)return;
    var cache=null,loading=false,lastQuery='';
    function open(){document.body.classList.add('live-search-open');panel.setAttribute('aria-hidden','false');if(back)back.setAttribute('aria-hidden','false');setTimeout(function(){input.focus()},80)}
    function shut(){document.body.classList.remove('live-search-open');panel.setAttribute('aria-hidden','true');if(back)back.setAttribute('aria-hidden','true')}
    function addTriggers(){
      var bar=$('#headerActionsBar');
      if(bar){var src=$$('.bui-hdr-item').some(function(x){return /^(search|cari)$/i.test(x.getAttribute('data-name')||'')});if(src&&!bar.querySelector('[data-header-item="search"]')){var wrap=document.createElement('div');wrap.className='header-action-item';wrap.setAttribute('data-header-item','search');wrap.innerHTML='<button class="icon-button" type="button" aria-label="Search" title="Search" data-live-search-trigger="true"><svg fill="none" stroke="currentColor" stroke-width="2.2" viewBox="0 0 24 24"><circle cx="10.5" cy="10.5" r="6.5"/><path d="m16 16 5 5"/></svg></button>';bar.appendChild(wrap)}}
      var mob=$('#mobileBottomNav');if(mob){var mb=$('[data-item="search"]',mob);if(mb&&!mb.classList.contains('is-hidden-item'))mb.setAttribute('data-live-search-trigger','true')}
    }
    function render(items,q){results.innerHTML='';if(!items.length){status.textContent='Tidak ada judul yang cocok dengan “'+q+'”.';return}status.textContent=items.length+' hasil ditemukan';items.slice(0,8).forEach(function(it){var a=document.createElement('a');a.className='bui-live-search-result';a.href=it.url;var im=document.createElement('img');im.loading='lazy';im.alt='';im.src=it.image||'';if(!it.image)im.style.display='none';var info=document.createElement('span'),title=document.createElement('strong'),meta=document.createElement('small'),arrow=document.createElement('span');title.textContent=it.title;meta.textContent=it.date||'Postingan';arrow.className='bui-search-arrow';arrow.textContent='↗';info.appendChild(title);info.appendChild(meta);a.appendChild(im);a.appendChild(info);a.appendChild(arrow);results.appendChild(a)})}
    function loadFeed(q){
      q=String(q||'').trim();if(q.length<2){results.innerHTML='';status.textContent='Ketik minimal 2 karakter untuk mencari judul postingan.';return}
      if(q===lastQuery)return;lastQuery=q;status.textContent='Mencari postingan…';results.innerHTML='';
      if(cache){var found=cache.filter(function(x){return x.title.toLowerCase().indexOf(q.toLowerCase())!==-1});render(found,q);return}
      if(loading)return;loading=true;
      var url='/feeds/posts/default?alt=json&max-results=500';
      fetch(url,{credentials:'same-origin'}).then(function(r){if(!r.ok)throw new Error('feed');return r.json()}).then(function(data){var entries=data&&data.feed&&data.feed.entry||[];cache=entries.map(function(e){var title=e.title&&e.title.$t||'Tanpa judul',links=e.link||[],link=links.find(function(l){return l.rel==='alternate'}),content=e.media$thumbnail&&e.media$thumbnail.url||'',date=e.published&&e.published.$t||'';return {title:title,url:link&&link.href||'#',image:content.replace(/\/s\d+-c\//,'/s160-c/'),date:date?new Date(date).toLocaleDateString(undefined,{year:'numeric',month:'short',day:'numeric'}):''}});render(cache.filter(function(x){return x.title.toLowerCase().indexOf(input.value.trim().toLowerCase())!==-1}),input.value.trim())}).catch(function(){status.textContent='Live Search tidak dapat memuat feed. Tekan Enter untuk membuka hasil pencarian Blogger.'}).finally(function(){loading=false})
    }
    document.addEventListener('click',function(e){var t=e.target.closest&&e.target.closest('[data-live-search-trigger]');if(t){e.preventDefault();open()}});
    if(close)close.addEventListener('click',shut);if(back)back.addEventListener('click',shut);document.addEventListener('keydown',function(e){if(e.key==='Escape')shut()});
    var timer=null;input.addEventListener('input',function(){clearTimeout(timer);timer=setTimeout(function(){loadFeed(input.value)},180)});
    if(form)form.addEventListener('submit',function(e){if(input.value.trim()){e.preventDefault();location.href='/search?q='+encodeURIComponent(input.value.trim())}});
    addTriggers();
  }

  function initV116Features(){
    var b=document.body;
    try{
      var st=getComputedStyle(b);
      var fDisp=parseInt(st.getPropertyValue('--bui-font-display'),10)||1;
      var fBody=parseInt(st.getPropertyValue('--bui-font-body'),10)||1;
      var fFoot=parseInt(st.getPropertyValue('--bui-footer-style'),10)||1;
      b.setAttribute('data-font-display',({1:'syne',2:'bebas',3:'archivo'})[fDisp]||'syne');
      b.setAttribute('data-font-body',({1:'space',2:'jakarta',3:'inter',4:'dmsans'})[fBody]||'space');
      b.setAttribute('data-footer-style',String(fFoot>=1&&fFoot<=7?fFoot:1));
    }catch(e){}

    if(b.getAttribute('data-homepage')==='true'){
      filterBelow('product');
    }

    var psc=$('#productShowcase');
    if(psc){
      var hdg=$('#sectionHeading');if(hdg)hdg.style.display='none';
      var pMap=productCfg();
      var dSrc=$('#pscDescSource'),dBox=$('#pscDesc');
      if(dSrc&&dBox&&dSrc.textContent.trim())dBox.textContent=dSrc.textContent.trim();
      if(pMap['product-wide-title']&&$('#pscWideTitle'))$('#pscWideTitle').textContent=pMap['product-wide-title'];
      if(pMap['product-wide-desc']&&$('#pscWideDesc'))$('#pscWideDesc').textContent=pMap['product-wide-desc'];
      if(pMap['product-stat1-num']&&$('#pscStat1Num'))$('#pscStat1Num').textContent=pMap['product-stat1-num'];
      if(pMap['product-stat1-text']&&$('#pscStat1Text'))$('#pscStat1Text').textContent=pMap['product-stat1-text'];
      if(pMap['product-stat2-num']&&$('#pscStat2Num'))$('#pscStat2Num').textContent=pMap['product-stat2-num'];
      if(pMap['product-stat2-text']&&$('#pscStat2Text'))$('#pscStat2Text').textContent=pMap['product-stat2-text'];

      $$('#pscFilterPills .psc-pill',psc).forEach(function(btn){
        btn.addEventListener('click',function(){
          var mode=btn.getAttribute('data-filter');
          $$('#pscFilterPills .psc-pill',psc).forEach(function(x){x.classList.toggle('active',x===btn)});
          $$('#postGrid .post-card').forEach(function(card){
            var info=card._info||getCardInfo(card);
            var price=Number(info.price)||0;
            var show=mode==='all'||(mode==='free'&&price===0)||(mode==='premium'&&price>0);
            card.classList.toggle('is-hidden',!show);
          });
        });
      });

      var grid=$('#postGrid');
      $$('#pscViewToggle .psc-view-btn',psc).forEach(function(btn){
        btn.addEventListener('click',function(){
          var view=btn.getAttribute('data-view');
          $$('#pscViewToggle .psc-view-btn',psc).forEach(function(x){x.classList.toggle('active',x===btn)});
          if(grid)grid.classList.toggle('is-list-view',view==='list');
        });
      });
    }
  }

  /* ---------- v1.1.6: konfigurasi Product Page, stok, tombol dinamis, ikon Tata Letak ---------- */
  var pCfg=null;
  function productCfg(){
    if(pCfg)return pCfg;
    pCfg={};
    $$('.psc-kv').forEach(function(el){
      var k=String(el.getAttribute('data-key')||'').trim().toLowerCase();
      var v=String(el.getAttribute('data-val')||'').trim().replace(/^http:\/\//,'');
      if(k&&v)pCfg[k]=v;
    });
    return pCfg;
  }
  function priceText(info){
    if(info.price)return money(info.price);
    return info.found?'Gratis':'Hubungi penjual';
  }
  function applyStockBadge(card,info){
    var b=$('.stock-badge',card);if(!b)return;
    var low=Number(productCfg()['low-stock'])||5,t='PRODUCT',st='';
    if(info.found){
      if(info.stock<1){t='STOK HABIS';st='out'}
      else if(info.stock<=low){t='SISA '+info.stock;st='low'}
      else t='STOK '+info.stock;
    }
    b.textContent=t;b.classList.toggle('is-low',st==='low');b.classList.toggle('is-out',st==='out');
  }
