  var shareOpener=null;
  function buildShareItems(url,title){
    var u=encodeURIComponent(url),t=encodeURIComponent(title),both=encodeURIComponent(title+' '+url);
    var og=document.querySelector('meta[property="og:image"]'),img=og?encodeURIComponent(og.getAttribute('content')||''):'';
    var ask=encodeURIComponent('Ringkas dan jelaskan artikel ini: '+url);
    var items=[
      {name:'WhatsApp',href:'https://wa.me/?text='+both,icon:'whatsapp'},
      {name:'Facebook',href:'https://www.facebook.com/sharer/sharer.php?u='+u,icon:'facebook'},
      {name:'X / Twitter',href:'https://twitter.com/intent/tweet?url='+u+'&text='+t,icon:'x'},
      {name:'Threads',href:'https://www.threads.net/intent/post?text='+both,icon:'threads'},
      {name:'Telegram',href:'https://t.me/share/url?url='+u+'&text='+t,icon:'telegram'},
      {name:'Bluesky',href:'https://bsky.app/intent/compose?text='+both,icon:'bluesky'},
      {name:'LinkedIn',href:'https://www.linkedin.com/sharing/share-offsite/?url='+u,icon:'linkedin'},
      {name:'Pinterest',href:'https://pinterest.com/pin/create/button/?url='+u+'&description='+t+(img?'&media='+img:''),icon:'pinterest'},
      {name:'Reddit',href:'https://www.reddit.com/submit?url='+u+'&title='+t,icon:'reddit'},
      {name:'Tumblr',href:'https://www.tumblr.com/widgets/share/tool?canonicalUrl='+u+'&title='+t,icon:'tumblr'},
      {name:'LINE',href:'https://social-plugins.line.me/lineit/share?url='+u,icon:'chat'},
      {name:'Email',href:'mailto:?subject='+t+'&body='+both,icon:'mail',self:true},
      {name:'SMS',href:'sms:?&body='+both,icon:'phone',self:true},
      {name:'ChatGPT',href:'https://chatgpt.com/?q='+ask,icon:'ai'},
      {name:'Claude',href:'https://claude.ai/new?q='+ask,icon:'ai'},
      {name:'Perplexity',href:'https://www.perplexity.ai/search?q='+ask,icon:'ai'},
      {name:'Print',act:'print',icon:'print'}
    ];
    if(navigator.share)items.push({name:'Lainnya',act:'native',icon:'share'});
    return items;
  }
  function iconSVG(name){
    var k=String(name||'').trim().toLowerCase().replace(/[^a-z0-9]+/g,'-').replace(/^-|-$/g,'');
    var p=ICON_PATHS[k]||ICON_PATHS[ICON_ALIAS[k]]||ICON_PATHS[k.split('-')[0]]||ICON_PATHS[ICON_ALIAS[k.split('-')[0]]]||ICON_PATHS.link;
    return '<svg aria-hidden="true" fill="none" stroke="currentColor" stroke-linecap="round" stroke-linejoin="round" stroke-width="2" viewBox="0 0 24 24">'+p+'</svg>';
  }
  function isExt(url){return /^https?:\/\//i.test(String(url||''))&&String(url).indexOf(location.host)===-1}
  function buildCardButtons(card,info){
    var box=$('.card-extra-actions',card);
    if(!box||!info.buttons||!info.buttons.length)return;
    box.innerHTML='';
    info.buttons.forEach(function(bt){
      var a=document.createElement('a');a.className='button card-extra';a.href=bt.url;a.setAttribute('data-btn',bt.key);
      if(isExt(bt.url)){a.target='_blank';a.rel='noopener'}
      a.innerHTML=iconSVG(bt.key)+'<span></span>';
      a.lastChild.textContent=bt.key.replace(/[-_]+/g,' ').replace(/\b[a-z]/g,function(c){return c.toUpperCase()});
      box.appendChild(a);
    });
  }
  function parseIconItems(sel){
    return $$(sel).map(function(el){
      var raw=String(el.getAttribute('data-name')||'').trim();
      var link=String(el.getAttribute('data-link')||'').trim();
      if(!raw)return null;
      var parts=raw.split('|');
      link=link.replace(/^https?:\/\/(?=\/)/i,'');
      if(/^(#|https?:\/\/)?$/i.test(link))link='';
      return {label:parts[0].trim(),icon:(parts[1]||'').trim(),link:link};
    }).filter(Boolean);
  }
  function applyProductLayout(){
    var psc=$('#productShowcase'),grid=$('#postGrid');
    if(!psc||!grid)return;
    var c=productCfg(),off=/^(off|no|false|0|hide)$/i;
    var cols=parseInt(c['grid-columns'],10);if(!(cols>=2&&cols<=4))cols=2;
    var list=String(c['layout']||'grid').toLowerCase()==='list';
    grid.style.setProperty('--prod-cols',cols);
    grid.style.setProperty('--prod-cols-md',Math.min(cols,3));
    grid.classList.toggle('is-list-view',list);
    $$('#pscViewToggle .psc-view-btn').forEach(function(x){x.classList.toggle('active',x.getAttribute('data-view')===(list?'list':'grid'))});
    var vs=$('#pscViewToggle'),fb=$('#pscFilterPills'),bar=$('.psc-bar',psc);
    var hideV=off.test(c['view-switcher']||''),hideF=off.test(c['filter-bar']||'');
    if(vs&&hideV)vs.style.display='none';
    if(fb&&hideF)fb.style.display='none';
    if(bar&&hideV&&hideF)bar.style.display='none';
  }

