    var nt=$('#notice');if(nt)nt.addEventListener('click',function(e){if(e.target.closest&&e.target.closest('.nt-close'))nt.classList.remove('show')});
    initObserver();
    renderSaved();
    initMetaSettings();
    var y=$('#currentYear');if(y)y.textContent=new Date().getFullYear();
  }
  if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',init);else init();
